def pg_manage_schema(connectionString=None, operation=None, tableName=None, schema=None, columns=None, operations=None, enumName=None, values=None, ifNotExists=None, **_extra):
    import json, os, datetime, hashlib, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:20]}"

    def _redact_connstr(dsn):
        if not isinstance(dsn, str):
            return None
        s = dsn.strip()
        if not s:
            return None
        if re.match(r"^pgconn_[A-Za-z0-9]+$", s):
            return s
        if "://" in s:
            s = re.sub(r"(?i)(postgres(?:ql)?://[^:/@\s]+:)[^@/\s]+@", r"\1****@", s)
        s = re.sub(r"(?i)\bpassword\s*=\s*([^\s;]+)", "password=****", s)
        return s

    def _parse_connstr_for_index(dsn):
        out = {"host": None, "port": None, "database_name": None, "username": None, "ssl_mode": None}
        if not isinstance(dsn, str):
            return out
        s = dsn.strip()
        if not s or re.match(r"^pgconn_[A-Za-z0-9]+$", s):
            return out
        if "://" not in s:
            kv = dict(re.findall(r"(?i)(\w+)\s*=\s*('[^']*'|\"[^\"]*\"|[^\s]+)", s))
            def _stripq(v):
                if v is None:
                    return None
                v = v.strip()
                if (len(v) >= 2) and ((v[0] == v[-1] == "'") or (v[0] == v[-1] == '"')):
                    return v[1:-1]
                return v
            host = _stripq(kv.get("host") or kv.get("hostname"))
            port = _stripq(kv.get("port"))
            dbn = _stripq(kv.get("dbname") or kv.get("database"))
            user = _stripq(kv.get("user") or kv.get("username"))
            sslm = _stripq(kv.get("sslmode"))
            out["host"] = host or None
            if port and str(port).isdigit():
                out["port"] = int(port)
            out["database_name"] = dbn or None
            out["username"] = user or None
            out["ssl_mode"] = sslm or None
            return out
        m = re.match(r"(?is)^(postgres(?:ql)?)(\+[^:]*)?://(.+)$", s)
        if not m:
            return out
        rest = m.group(3)
        if "?" in rest:
            rest, q = rest.split("?", 1)
        else:
            q = ""
        if "/" in rest:
            before, path = rest.split("/", 1)
        else:
            before, path = rest, ""
        auth = None
        hostport = before
        if "@" in before:
            auth, hostport = before.rsplit("@", 1)
        if auth:
            if ":" in auth:
                out["username"] = auth.split(":", 1)[0] or None
            else:
                out["username"] = auth or None
        host = hostport
        port = None
        if hostport.startswith("["):
            m6 = re.match(r"^\[([^\]]+)\](?::(\d+))?$", hostport)
            if m6:
                host = m6.group(1)
                port = int(m6.group(2)) if m6.group(2) else None
        else:
            if ":" in hostport:
                h, p = hostport.rsplit(":", 1)
                if p.isdigit():
                    host, port = h, int(p)
        out["host"] = host or None
        out["port"] = port
        out["database_name"] = path.split("/", 1)[0] if path else None
        if q:
            for part in q.split("&"):
                if "=" in part:
                    k, v = part.split("=", 1)
                    if k.lower() == "sslmode":
                        out["ssl_mode"] = v or None
        return out

    def _resolve_connection(conn_str):
        conns = _load("pg_connections.json")
        if conn_str is None:
            for c in conns:
                if isinstance(c, dict) and c.get("status") == "active":
                    return c, conns, False
            return None, conns, False
        if not isinstance(conn_str, str) or not conn_str.strip():
            return _err("VALIDATION_ERROR", "connectionString must be a non-empty string when provided."), conns, False
        s = conn_str.strip()
        if re.match(r"^pgconn_[A-Za-z0-9]+$", s):
            for c in conns:
                if isinstance(c, dict) and c.get("id") == s and c.get("status") != "deleted":
                    if c.get("status") != "active":
                        return _err("UNAUTHORIZED", "Referenced connection is not active."), conns, False
                    return c, conns, False
            return _err("NOT_FOUND", "connectionString references an unknown connection id."), conns, False
        red = _redact_connstr(s)
        for c in conns:
            if isinstance(c, dict) and c.get("connection_string_redacted") == red and c.get("status") != "deleted":
                if c.get("status") != "active":
                    return _err("UNAUTHORIZED", "Resolved connection profile is not active."), conns, False
                return c, conns, False
        parsed = _parse_connstr_for_index(s)
        port = parsed.get("port")
        if port is not None and not (1 <= int(port) <= 65535):
            return _err("VALIDATION_ERROR", "connectionString contains an invalid port; must be 1..65535."), conns, False
        sslm = parsed.get("ssl_mode")
        if sslm is not None:
            allowed_ssl = {"disable", "allow", "prefer", "require", "verify-ca", "verify-full"}
            if str(sslm) not in allowed_ssl:
                parsed["ssl_mode"] = None
        now = _now()
        newc = {
            "id": _new_id("pgconn"),
            "display_name": None,
            "connection_string_redacted": red,
            "connection_string_secret_ref": None,
            "host": parsed.get("host"),
            "port": parsed.get("port"),
            "database_name": parsed.get("database_name"),
            "username": parsed.get("username"),
            "ssl_mode": parsed.get("ssl_mode"),
            "status": "active",
            "last_tested_at": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now,
        }
        conns.append(newc)
        _save("pg_connections.json", conns)
        return newc, conns, True

    # validate operation enum
    allowed_ops = {"get_info", "create_table", "alter_table", "get_enums", "create_enum"}
    if not isinstance(operation, str) or operation not in allowed_ops:
        now = _now()
        op_id = _new_id("pgop")
        ops = _load("pg_operations.json")
        params = {
            "connectionString": connectionString, "operation": operation, "tableName": tableName, "schema": schema,
            "columns": columns, "operations": operations, "enumName": enumName, "values": values, "ifNotExists": ifNotExists
        }
        ops.append({
            "id": op_id,
            "tool_name": "pg_manage_schema",
            "connection_id": None,
            "source_connection_id": None,
            "target_connection_id": None,
            "operation_group": "schema",
            "requested_operation": operation if isinstance(operation, str) else None,
            "params": params,
            "params_hash": None,
            "status": "failed",
            "started_at": now,
            "finished_at": now,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "VALIDATION_ERROR",
            "error_message": "operation must be one of: get_info, create_table, alter_table, get_enums, create_enum.",
            "created_at": now,
            "updated_at": now
        })
        _save("pg_operations.json", ops)
        return _err("VALIDATION_ERROR", "operation must be one of: get_info, create_table, alter_table, get_enums, create_enum.", operation_id=op_id)

    # defaults
    eff_schema = schema if isinstance(schema, str) and schema.strip() else "public"

    # per-operation required fields
    if operation in ("create_table", "alter_table"):
        if not isinstance(tableName, str) or not tableName.strip():
            msg = "tableName is required for operation '%s'." % operation
            now = _now()
            op_id = _new_id("pgop")
            ops = _load("pg_operations.json")
            params = {
                "connectionString": connectionString, "operation": operation, "tableName": tableName, "schema": eff_schema,
                "columns": columns, "operations": operations, "enumName": enumName, "values": values, "ifNotExists": ifNotExists
            }
            ops.append({
                "id": op_id, "tool_name": "pg_manage_schema",
                "connection_id": None, "source_connection_id": None, "target_connection_id": None,
                "operation_group": "schema", "requested_operation": operation,
                "params": params, "params_hash": None,
                "status": "failed", "started_at": now, "finished_at": now,
                "duration_ms": int((time.time() - t0) * 1000),
                "error_code": "VALIDATION_ERROR", "error_message": msg,
                "created_at": now, "updated_at": now
            })
            _save("pg_operations.json", ops)
            return _err("VALIDATION_ERROR", msg, operation_id=op_id)

    if operation == "create_table":
        if not isinstance(columns, list) or len(columns) == 0:
            msg = "columns is required for create_table and must be a non-empty array."
            now = _now()
            op_id = _new_id("pgop")
            ops = _load("pg_operations.json")
            params = {
                "connectionString": connectionString, "operation": operation, "tableName": tableName, "schema": eff_schema,
                "columns": columns, "operations": operations, "enumName": enumName, "values": values, "ifNotExists": ifNotExists
            }
            ops.append({
                "id": op_id, "tool_name": "pg_manage_schema",
                "connection_id": None, "source_connection_id": None, "target_connection_id": None,
                "operation_group": "schema", "requested_operation": operation,
                "params": params, "params_hash": None,
                "status": "failed", "started_at": now, "finished_at": now,
                "duration_ms": int((time.time() - t0) * 1000),
                "error_code": "VALIDATION_ERROR", "error_message": msg,
                "created_at": now, "updated_at": now
            })
            _save("pg_operations.json", ops)
            return _err("VALIDATION_ERROR", msg, operation_id=op_id)
        # validate column objects shape (light)
        for i, col in enumerate(columns):
            if not isinstance(col, dict):
                return _err("VALIDATION_ERROR", f"columns[{i}] must be an object.")
            if not isinstance(col.get("name"), str) or not col.get("name").strip():
                return _err("VALIDATION_ERROR", f"columns[{i}].name is required.")
            if not isinstance(col.get("type"), str) or not col.get("type").strip():
                return _err("VALIDATION_ERROR", f"columns[{i}].type is required.")
            if col.get("nullable") is not None and not isinstance(col.get("nullable"), bool):
                return _err("VALIDATION_ERROR", f"columns[{i}].nullable must be boolean when provided.")
            if col.get("default") is not None and not isinstance(col.get("default"), str):
                return _err("VALIDATION_ERROR", f"columns[{i}].default must be string when provided.")
    if operation == "alter_table":
        if not isinstance(operations, list) or len(operations) == 0:
            return _err("VALIDATION_ERROR", "operations is required for alter_table and must be a non-empty array.")
        for i, op in enumerate(operations):
            if not isinstance(op, dict):
                return _err("VALIDATION_ERROR", f"operations[{i}] must be an object.")
            if op.get("type") not in ("add", "alter", "drop"):
                return _err("VALIDATION_ERROR", f"operations[{i}].type must be one of add/alter/drop.")
            if not isinstance(op.get("columnName"), str) or not op.get("columnName").strip():
                return _err("VALIDATION_ERROR", f"operations[{i}].columnName is required.")
            if op.get("dataType") is not None and not isinstance(op.get("dataType"), str):
                return _err("VALIDATION_ERROR", f"operations[{i}].dataType must be string when provided.")
            if op.get("nullable") is not None and not isinstance(op.get("nullable"), bool):
                return _err("VALIDATION_ERROR", f"operations[{i}].nullable must be boolean when provided.")
            if op.get("default") is not None and not isinstance(op.get("default"), str):
                return _err("VALIDATION_ERROR", f"operations[{i}].default must be string when provided.")

    if operation == "create_enum":
        if not isinstance(enumName, str) or not enumName.strip():
            return _err("VALIDATION_ERROR", "enumName is required for create_enum.")
        if not isinstance(values, list) or len(values) == 0 or any((not isinstance(v, str) or not v) for v in values):
            return _err("VALIDATION_ERROR", "values is required for create_enum and must be a non-empty array of strings.")
        if ifNotExists is not None and not isinstance(ifNotExists, bool):
            return _err("VALIDATION_ERROR", "ifNotExists must be boolean when provided.")

    # resolve connection
    resolved, conns, _created = _resolve_connection(connectionString)
    if isinstance(resolved, dict) and "error" in resolved:
        now = _now()
        op_id = _new_id("pgop")
        ops = _load("pg_operations.json")
        params = {
            "connectionString": connectionString, "operation": operation, "tableName": tableName, "schema": eff_schema,
            "columns": columns, "operations": operations, "enumName": enumName, "values": values, "ifNotExists": ifNotExists
        }
        err = resolved["error"]
        ops.append({
            "id": op_id, "tool_name": "pg_manage_schema",
            "connection_id": None, "source_connection_id": None, "target_connection_id": None,
            "operation_group": "schema", "requested_operation": operation,
            "params": params, "params_hash": None,
            "status": "failed", "started_at": now, "finished_at": now,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": err.get("code"), "error_message": err.get("message"),
            "created_at": now, "updated_at": now
        })
        _save("pg_operations.json", ops)
        return _err(err.get("code"), err.get("message"), operation_id=op_id)

    if resolved is None:
        now = _now()
        op_id = _new_id("pgop")
        ops = _load("pg_operations.json")
        params = {
            "connectionString": connectionString, "operation": operation, "tableName": tableName, "schema": eff_schema,
            "columns": columns, "operations": operations, "enumName": enumName, "values": values, "ifNotExists": ifNotExists
        }
        ops.append({
            "id": op_id, "tool_name": "pg_manage_schema",
            "connection_id": None, "source_connection_id": None, "target_connection_id": None,
            "operation_group": "schema", "requested_operation": operation,
            "params": params, "params_hash": None,
            "status": "failed", "started_at": now, "finished_at": now,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "UNAUTHORIZED", "error_message": "No active connection available to serve request.",
            "created_at": now, "updated_at": now
        })
        _save("pg_operations.json", ops)
        return _err("UNAUTHORIZED", "No active connection available to serve request.", operation_id=op_id)

    # Create operation row
    now = _now()
    op_id = _new_id("pgop")
    params = {
        "connectionString": connectionString,
        "operation": operation,
        "schema": eff_schema,
        "tableName": tableName,
        "columns": columns,
        "operations": operations,
        "enumName": enumName,
        "values": values,
        "ifNotExists": ifNotExists
    }
    ops_rows = _load("pg_operations.json")
    op_row = {
        "id": op_id,
        "tool_name": "pg_manage_schema",
        "connection_id": resolved.get("id"),
        "source_connection_id": None,
        "target_connection_id": None,
        "operation_group": "schema",
        "requested_operation": operation,
        "params": params,
        "params_hash": None,
        "status": "running",
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    ops_rows.append(op_row)
    _save("pg_operations.json", ops_rows)

    # Apply "effects" to metadata cache (stale marking) for mutating ops
    cache = _load("pg_object_metadata_cache.json")
    touched_identities = []

    if operation in ("create_table", "alter_table"):
        ident = f"{eff_schema}.{tableName}"
        touched_identities.append(ident)
        # also columns identities could change on alter, but unknown; mark table identity only
    if operation == "create_enum":
        ident = f"{eff_schema}.{enumName}"
        touched_identities.append(ident)

    if touched_identities:
        now2 = _now()
        for row in cache:
            if not isinstance(row, dict):
                continue
            if row.get("connection_id") != resolved.get("id"):
                continue
            if row.get("object_identity") in touched_identities and row.get("status") in ("current", "stale"):
                row["status"] = "stale"
                row["updated_at"] = now2
        _save("pg_object_metadata_cache.json", cache)

    # Finish operation and write result (schema_info)
    finished = _now()
    duration_ms = int((time.time() - t0) * 1000)
    ops_rows = _load("pg_operations.json")
    for r in ops_rows:
        if isinstance(r, dict) and r.get("id") == op_id:
            r["status"] = "succeeded"
            r["finished_at"] = finished
            r["duration_ms"] = duration_ms
            r["updated_at"] = finished
            break
    _save("pg_operations.json", ops_rows)

    results = _load("pg_operation_results.json")
    res_id = _new_id("pgres")
    result_payload = {
        "operation": operation,
        "schema": eff_schema,
        "tableName": tableName,
        "enumName": enumName,
        "changed": operation in ("create_table", "alter_table", "create_enum"),
        "touched_object_identities": touched_identities,
        "note": "Schema operation recorded; database not contacted in this environment."
    }
    results.append({
        "id": res_id,
        "operation_id": op_id,
        "result_type": "schema_info",
        "content_format": "json",
        "content_json": result_payload,
        "content_text": None,
        "external_blob_ref": None,
        "rows_returned": None,
        "rows_affected": 1 if result_payload["changed"] else 0,
        "warnings": [],
        "created_at": finished,
        "updated_at": finished
    })
    _save("pg_operation_results.json", results)

    return {"operation": op_row, "result": results[-1]}

def pg_manage_functions(connectionString=None, operation=None, functionName=None, schema=None, parameters=None, returnType=None, functionBody=None, language=None, volatility=None, security=None, replace=None, ifExists=None, cascade=None, **_extra):
    import json, os, datetime, hashlib, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
