                    return _err("UNAUTHORIZED", "Resolved connection profile is not active."), conns, False
                return c, conns, False
        parsed = _parse_connstr_for_index(s)
        port = parsed.get("port")
        if port is not None and not (1 <= int(port) <= 65535):
            return _err("VALIDATION_ERROR", "connectionString contains an invalid port; must be 1..65535."), conns, False
        sslm = parsed.get("ssl_mode")
        if sslm is not None:
            allowed_ssl = {"disable", "allow", "prefer", "require", "verify-ca", "verify-full"}
            if str(sslm) not in allowed_ssl:
                parsed["ssl_mode"] = None
        now = _now()
        newc = {
            "id": _new_id("pgconn"),
            "display_name": None,
            "connection_string_redacted": red,
            "connection_string_secret_ref": None,
            "host": parsed.get("host"),
            "port": parsed.get("port"),
            "database_name": parsed.get("database_name"),
            "username": parsed.get("username"),
            "ssl_mode": parsed.get("ssl_mode"),
            "status": "active",
            "last_tested_at": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now,
        }
        conns.append(newc)
        _save("pg_connections.json", conns)
        return newc, conns, True

    allowed_ops = {"get", "create", "drop"}
    if not isinstance(operation, str) or operation not in allowed_ops:
        now = _now()
        op_id = _new_id("pgop")
        ops = _load("pg_operations.json")
        params = {
            "connectionString": connectionString, "operation": operation, "functionName": functionName, "schema": schema,
            "parameters": parameters, "returnType": returnType, "functionBody": functionBody, "language": language,
            "volatility": volatility, "security": security, "replace": replace, "ifExists": ifExists, "cascade": cascade
        }
        ops.append({
            "id": op_id, "tool_name": "pg_manage_functions",
            "connection_id": None, "source_connection_id": None, "target_connection_id": None,
            "operation_group": "schema", "requested_operation": operation if isinstance(operation, str) else None,
            "params": params, "params_hash": None,
            "status": "failed", "started_at": now, "finished_at": now,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "VALIDATION_ERROR",
            "error_message": "operation must be one of: get, create, drop.",
            "created_at": now, "updated_at": now
        })
        _save("pg_operations.json", ops)
        return _err("VALIDATION_ERROR", "operation must be one of: get, create, drop.", operation_id=op_id)

    eff_schema = schema if isinstance(schema, str) and schema.strip() else "public"

    # per-op validation
    if operation in ("create", "drop"):
        if not isinstance(functionName, str) or not functionName.strip():
            return _err("VALIDATION_ERROR", f"functionName is required for operation '{operation}'.")
    if operation == "create":
        if parameters is None:
            return _err("VALIDATION_ERROR", "parameters is required for create (use empty string \"\" for no parameters).")
        if not isinstance(parameters, str):
            return _err("VALIDATION_ERROR", "parameters must be a string.")
        if not isinstance(returnType, str) or not returnType.strip():
            return _err("VALIDATION_ERROR", "returnType is required for create.")
        if not isinstance(functionBody, str) or not functionBody.strip():
            return _err("VALIDATION_ERROR", "functionBody is required for create.")
        if language is None:
            language = "plpgsql"
        if volatility is None:
            volatility = "VOLATILE"
        if security is None:
            security = "INVOKER"
        if language not in ("sql", "plpgsql", "plpython3u"):
            return _err("VALIDATION_ERROR", "language must be one of: sql, plpgsql, plpython3u.")
        if volatility not in ("VOLATILE", "STABLE", "IMMUTABLE"):
            return _err("VALIDATION_ERROR", "volatility must be one of: VOLATILE, STABLE, IMMUTABLE.")
        if security not in ("INVOKER", "DEFINER"):
            return _err("VALIDATION_ERROR", "security must be one of: INVOKER, DEFINER.")
        if replace is not None and not isinstance(replace, bool):
            return _err("VALIDATION_ERROR", "replace must be boolean when provided.")
    if operation == "drop":
        if parameters is not None and not isinstance(parameters, str):
            return _err("VALIDATION_ERROR", "parameters must be a string when provided.")
        if ifExists is not None and not isinstance(ifExists, bool):
            return _err("VALIDATION_ERROR", "ifExists must be boolean when provided.")
        if cascade is not None and not isinstance(cascade, bool):
            return _err("VALIDATION_ERROR", "cascade must be boolean when provided.")

    resolved, conns, _created = _resolve_connection(connectionString)
    if isinstance(resolved, dict) and "error" in resolved:
        now = _now()
        op_id = _new_id("pgop")
        ops = _load("pg_operations.json")
        err = resolved["error"]
        params = {
            "connectionString": connectionString, "operation": operation, "functionName": functionName, "schema": eff_schema,
            "parameters": parameters, "returnType": returnType, "functionBody": functionBody, "language": language,
            "volatility": volatility, "security": security, "replace": replace, "ifExists": ifExists, "cascade": cascade
        }
        ops.append({
            "id": op_id, "tool_name": "pg_manage_functions",
            "connection_id": None, "source_connection_id": None, "target_connection_id": None,
            "operation_group": "schema", "requested_operation": operation,
            "params": params, "params_hash": None,
            "status": "failed", "started_at": now, "finished_at": now,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": err.get("code"), "error_message": err.get("message"),
            "created_at": now, "updated_at": now
        })
        _save("pg_operations.json", ops)
        return _err(err.get("code"), err.get("message"), operation_id=op_id)

    if resolved is None:
        now = _now()
        op_id = _new_id("pgop")
        ops = _load("pg_operations.json")
        params = {
            "connectionString": connectionString, "operation": operation, "functionName": functionName, "schema": eff_schema,
            "parameters": parameters, "returnType": returnType, "functionBody": functionBody, "language": language,
            "volatility": volatility, "security": security, "replace": replace, "ifExists": ifExists, "cascade": cascade
        }
        ops.append({
            "id": op_id, "tool_name": "pg_manage_functions",
            "connection_id": None, "source_connection_id": None, "target_connection_id": None,
            "operation_group": "schema", "requested_operation": operation,
            "params": params, "params_hash": None,
            "status": "failed", "started_at": now, "finished_at": now,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "UNAUTHORIZED", "error_message": "No active connection available to serve request.",
            "created_at": now, "updated_at": now
        })
        _save("pg_operations.json", ops)
        return _err("UNAUTHORIZED", "No active connection available to serve request.", operation_id=op_id)

    # create operation row
    now = _now()
    op_id = _new_id("pgop")
    params = {
        "connectionString": connectionString,
        "operation": operation,
        "schema": eff_schema,
        "functionName": functionName,
        "parameters": parameters,
        "returnType": returnType,
        "functionBody": functionBody,
        "language": language,
        "volatility": volatility,
        "security": security,
        "replace": replace,
        "ifExists": ifExists,
        "cascade": cascade
    }
    ops = _load("pg_operations.json")
    op_row = {
        "id": op_id,
        "tool_name": "pg_manage_functions",
        "connection_id": resolved.get("id"),
        "source_connection_id": None,
        "target_connection_id": None,
        "operation_group": "schema",
        "requested_operation": operation,
        "params": params,
        "params_hash": None,
        "status": "running",
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op_row)
    _save("pg_operations.json", ops)

    # "effect": mark metadata cache stale for function identity on mutations
    cache = _load("pg_object_metadata_cache.json")
    touched = []
    if operation in ("create", "drop"):
        sig = parameters if isinstance(parameters, str) else ""
        ident = f"{eff_schema}.{functionName}({sig})"
        touched.append(ident)
        now2 = _now()
        for row in cache:
            if not isinstance(row, dict):
                continue
            if row.get("connection_id") != resolved.get("id"):
                continue
            if row.get("object_identity") == ident and row.get("status") in ("current", "stale"):
                row["status"] = "stale"
                row["updated_at"] = now2
        _save("pg_object_metadata_cache.json", cache)

    # finish and result row
    finished = _now()
    duration_ms = int((time.time() - t0) * 1000)
    ops = _load("pg_operations.json")
    for r in ops:
        if isinstance(r, dict) and r.get("id") == op_id:
            r["status"] = "succeeded"
            r["finished_at"] = finished
            r["duration_ms"] = duration_ms
            r["updated_at"] = finished
            break
    _save("pg_operations.json", ops)

    results = _load("pg_operation_results.json")
    res_id = _new_id("pgres")
    payload = {
        "operation": operation,
        "schema": eff_schema,
        "functionName": functionName,
        "parameters": parameters,
        "changed": operation in ("create", "drop"),
        "touched_object_identities": touched,
        "note": "Function operation recorded; database not contacted in this environment."
    }
    results.append({
        "id": res_id,
        "operation_id": op_id,
        "result_type": "schema_info",
        "content_format": "json",
        "content_json": payload,
        "content_text": None,
        "external_blob_ref": None,
        "rows_returned": None,
        "rows_affected": 1 if payload["changed"] else 0,
        "warnings": [],
        "created_at": finished,
        "updated_at": finished
    })
    _save("pg_operation_results.json", results)

    return {"operation": op_row, "result": results[-1]}

def pg_manage_triggers(operation, connectionString=None, schema=None, tableName=None, triggerName=None, functionName=None, timing=None, events=None, forEach=None, when=None, replace=None, ifExists=None, cascade=None, enable=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- helpers ----
    def _typecheck_str(v, name):
        if v is None:
            return None
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{name} must be a string")
        return None

    def _typecheck_bool(v, name):
        if v is None:
            return None
        if not isinstance(v, bool):
            return _err("VALIDATION_ERROR", f"{name} must be a boolean")
        return None

    def _typecheck_arr_str(v, name):
        if v is None:
            return None
        if not isinstance(v, list) or any(not isinstance(x, str) for x in v):
            return _err("VALIDATION_ERROR", f"{name} must be an array of strings")
        return None

    def _iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _redact_dsn(dsn):
        # remove password=... and :password@ in URI form; best-effort
        if not isinstance(dsn, str) or not dsn:
            return None
        s = dsn.strip()
        # key/value: password=... (single token)
        s = re.sub(r"(?i)\bpassword\s*=\s*[^ \t\r\n]+", "password=REDACTED", s)
        # uri user:pass@
        s = re.sub(r":([^:@/]+)@", ":REDACTED@", s)
        return s

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time())+os.urandom(8).hex()).encode()).hexdigest()[:24]}"

    def _find_or_create_connection(dsn):
        conns = _load("pg_connections.json")
        if dsn is None:
            # ambient auth: pick any usable active connection
            for c in conns:
                if c.get("status") == "active":
                    return c, conns, False
            return None, conns, False

        red = _redact_dsn(dsn)
        if red is None:
            return _err("VALIDATION_ERROR", "connectionString must be a non-empty string"), conns, False

        for c in conns:
            if c.get("connection_string_redacted") == red and c.get("status") != "deleted":
                # if disabled, still resolvable but cannot be used
                return c, conns, False

        # create new
        cid = _new_id("pgc")
        row = {
            "id": cid,
            "display_name": None,
            "connection_string_redacted": red,
            "connection_string_secret_ref": None,
            "host": None,
            "port": None,
            "database_name": None,
            "username": None,
            "ssl_mode": None,
            "status": "active",
            "last_tested_at": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now,
        }
        conns.append(row)
        return row, conns, True

    def _log_op(tool, group, requested_op, conn_id, params_obj, status, error_code=None, error_message=None, started_at=None, finished_at=None, duration_ms=None):
        ops = _load("pg_operations.json")
        oid = _new_id("pgo")
        row = {
            "id": oid,
            "tool_name": tool,
            "connection_id": conn_id,
            "source_connection_id": None,
            "target_connection_id": None,
            "operation_group": group,
            "requested_operation": requested_op,
            "params": params_obj,
            "params_hash": hashlib.sha256(json.dumps(params_obj, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest(),
            "status": status,
            "started_at": started_at,
            "finished_at": finished_at,
            "duration_ms": duration_ms,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("pg_operations.json", ops)
        return row

    def _upsert_result(operation_id, result_type, content_format, content_json=None, content_text=None, external_blob_ref=None, rows_returned=None, rows_affected=None, warnings=None):
        if warnings is None:
            warnings = []
        results = _load("pg_operation_results.json")
        # unique(operation_id, result_type)
        existing = None
        for r in results:
            if r.get("operation_id") == operation_id and r.get("result_type") == result_type:
                existing = r
                break
        if existing is None:
            rid = _new_id("pgor")
            row = {
                "id": rid,
                "operation_id": operation_id,
                "result_type": result_type,
                "content_format": content_format,
                "content_json": content_json,
                "content_text": content_text,
                "external_blob_ref": external_blob_ref,
                "rows_returned": rows_returned,
                "rows_affected": rows_affected,
                "warnings": warnings if isinstance(warnings, list) else [],
                "created_at": now,
                "updated_at": now,
            }
            results.append(row)
        else:
            existing["content_format"] = content_format
            existing["content_json"] = content_json
            existing["content_text"] = content_text
            existing["external_blob_ref"] = external_blob_ref
            existing["rows_returned"] = rows_returned
            existing["rows_affected"] = rows_affected
            existing["warnings"] = warnings if isinstance(warnings, list) else []
            existing["updated_at"] = now
        _save("pg_operation_results.json", results)

    def _mark_cache_stale(connection_id, object_identities):
        cache = _load("pg_object_metadata_cache.json")
        changed = 0
        for e in cache:
            if e.get("connection_id") != connection_id:
                continue
            if e.get("object_identity") in object_identities and e.get("status") in ("current", "stale"):
                if e.get("status") != "stale":
                    e["status"] = "stale"
                    e["updated_at"] = now
                    changed += 1
        if changed:
            _save("pg_object_metadata_cache.json", cache)

    # ---- validate inputs ----
    if operation not in ("get", "create", "drop", "set_state"):
        # Still must record op row
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": schema, "tableName": tableName,
                      "triggerName": triggerName, "functionName": functionName, "timing": timing, "events": events, "forEach": forEach,
                      "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
        op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed",
                         error_code="VALIDATION_ERROR", error_message="Invalid operation")
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
        return _err("VALIDATION_ERROR", "operation must be one of get/create/drop/set_state")

    for chk in (
        _typecheck_str(connectionString, "connectionString"),
        _typecheck_str(schema, "schema"),
        _typecheck_str(tableName, "tableName"),
        _typecheck_str(triggerName, "triggerName"),
        _typecheck_str(functionName, "functionName"),
        _typecheck_str(timing, "timing"),
        _typecheck_arr_str(events, "events"),
        _typecheck_str(forEach, "forEach"),
        _typecheck_str(when, "when"),
        _typecheck_bool(replace, "replace"),
        _typecheck_bool(ifExists, "ifExists"),
        _typecheck_bool(cascade, "cascade"),
        _typecheck_bool(enable, "enable"),
    ):
        if chk is not None:
            params_obj = {
                "operation": operation,
                "connectionString": _redact_dsn(connectionString),
                "schema": schema if schema is not None else "public",
                "tableName": tableName,
                "triggerName": triggerName,
                "functionName": functionName,
                "timing": timing,
                "events": events,
                "forEach": forEach,
                "when": when,
                "replace": replace,
                "ifExists": ifExists,
                "cascade": cascade,
                "enable": enable,
            }
            op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed",
                             error_code="VALIDATION_ERROR", error_message=chk["error"]["message"])
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
            return chk

    eff_schema = schema if schema is not None else "public"

    # operation-specific requirements and defaults
    if operation == "create":
        if not tableName:
            msg = "tableName is required for create"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                          "triggerName": triggerName, "functionName": functionName, "timing": timing, "events": events, "forEach": forEach,
                          "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
            op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
            return _err("VALIDATION_ERROR", msg)
        if not triggerName:
            msg = "triggerName is required for create"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                          "triggerName": triggerName, "functionName": functionName, "timing": timing, "events": events, "forEach": forEach,
                          "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
            op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
            return _err("VALIDATION_ERROR", msg)
        if not functionName:
            msg = "functionName is required for create"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                          "triggerName": triggerName, "functionName": functionName, "timing": timing, "events": events, "forEach": forEach,
                          "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
            op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
            return _err("VALIDATION_ERROR", msg)

        eff_timing = timing if timing is not None else "AFTER"
        if eff_timing not in ("BEFORE", "AFTER", "INSTEAD OF"):
            msg = "timing must be one of BEFORE/AFTER/INSTEAD OF"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                          "triggerName": triggerName, "functionName": functionName, "timing": eff_timing, "events": events, "forEach": forEach,
                          "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
            op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
            return _err("VALIDATION_ERROR", msg)

        eff_events = events if events is not None else ["INSERT"]
        if not isinstance(eff_events, list) or len(eff_events) == 0:
            msg = "events must be a non-empty array for create"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                          "triggerName": triggerName, "functionName": functionName, "timing": eff_timing, "events": eff_events, "forEach": forEach,
                          "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
            op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
            return _err("VALIDATION_ERROR", msg)
        for ev in eff_events:
            if ev not in ("INSERT", "UPDATE", "DELETE", "TRUNCATE"):
                msg = "events contains invalid value"
                params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                              "triggerName": triggerName, "functionName": functionName, "timing": eff_timing, "events": eff_events, "forEach": forEach,
                              "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
                op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
                _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
                return _err("VALIDATION_ERROR", msg)

        eff_for_each = forEach if forEach is not None else "ROW"
        if eff_for_each not in ("ROW", "STATEMENT"):
            msg = "forEach must be one of ROW/STATEMENT"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                          "triggerName": triggerName, "functionName": functionName, "timing": eff_timing, "events": eff_events, "forEach": eff_for_each,
                          "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
            op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
            return _err("VALIDATION_ERROR", msg)
    else:
        eff_timing = timing
        eff_events = events
        eff_for_each = forEach

    if operation in ("drop", "set_state"):
        if not tableName:
            msg = "tableName is required"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                          "triggerName": triggerName, "functionName": functionName, "timing": eff_timing, "events": eff_events, "forEach": eff_for_each,
                          "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
            op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
            return _err("VALIDATION_ERROR", msg)
        if not triggerName:
            msg = "triggerName is required"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                          "triggerName": triggerName, "functionName": functionName, "timing": eff_timing, "events": eff_events, "forEach": eff_for_each,
                          "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
            op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
            return _err("VALIDATION_ERROR", msg)
    if operation == "set_state" and enable is None:
        msg = "enable is required for set_state"
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                      "triggerName": triggerName, "functionName": functionName, "timing": eff_timing, "events": eff_events, "forEach": eff_for_each,
                      "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
        op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
        return _err("VALIDATION_ERROR", msg)

    # Resolve connection
    conn_row, conns, created_conn = _find_or_create_connection(connectionString)
    if isinstance(conn_row, dict) and "error" in conn_row:
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                      "triggerName": triggerName, "functionName": functionName, "timing": eff_timing, "events": eff_events, "forEach": eff_for_each,
                      "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
        op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed",
                         error_code="VALIDATION_ERROR", error_message=conn_row["error"]["message"])
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
        return conn_row
    if conn_row is None:
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                      "triggerName": triggerName, "functionName": functionName, "timing": eff_timing, "events": eff_events, "forEach": eff_for_each,
                      "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
        op_row = _log_op("pg_manage_triggers", "schema", operation, None, params_obj, "failed",
                         error_code="UNAUTHORIZED", error_message="No active connection available")
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
        return _err("UNAUTHORIZED", "No active connection available")
    if conn_row.get("status") != "active":
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName,
                      "triggerName": triggerName, "functionName": functionName, "timing": eff_timing, "events": eff_events, "forEach": eff_for_each,
                      "when": when, "replace": replace, "ifExists": ifExists, "cascade": cascade, "enable": enable}
        op_row = _log_op("pg_manage_triggers", "schema", operation, conn_row.get("id"), params_obj, "failed",
                         error_code="UNAUTHORIZED", error_message="Connection is not active")
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=[])
        return _err("UNAUTHORIZED", "Connection is not active")

    if created_conn:
        _save("pg_connections.json", conns)

    # Build params persisted (secrets redacted already)
    params_obj = {
        "operation": operation,
        "connectionString": _redact_dsn(connectionString),
        "schema": eff_schema,
        "tableName": tableName,
        "triggerName": triggerName,
        "functionName": functionName,
        "timing": eff_timing if operation == "create" else timing,
        "events": eff_events if operation == "create" else events,
        "forEach": eff_for_each if operation == "create" else forEach,
        "when": when,
        "replace": replace if replace is not None else False if operation == "create" else replace,
        "ifExists": ifExists if ifExists is not None else False,
        "cascade": cascade if cascade is not None else False,
        "enable": enable,
    }

    # Start op row (queued->running->done simulated)
    started_at = _iso_z()
    op_row = _log_op("pg_manage_triggers", "schema", operation, conn_row["id"], params_obj, "running",
                     started_at=started_at, finished_at=None, duration_ms=None)

    cache = _load("pg_object_metadata_cache.json")

    def _find_trigger_entries():
        out = []
        for e in cache:
            if e.get("connection_id") != conn_row["id"]:
                continue
            if e.get("object_type") != "trigger":
                continue
            if e.get("status") == "deleted":
                continue
            if e.get("schema") != eff_schema:
                continue
            attrs = e.get("attributes") or {}
            if tableName and attrs.get("table") != tableName:
                continue
            if triggerName and e.get("object_name") != triggerName:
                continue
            out.append(e)
        return out

    warnings = []
    changed = []
    details = []

    if operation == "get":
        rows = []
        for e in _find_trigger_entries():
            rows.append({
                "schema": e.get("schema"),
                "tableName": (e.get("attributes") or {}).get("table"),
                "triggerName": e.get("object_name"),
                "definition": e.get("definition"),
                "comment": e.get("comment"),
                "attributes": e.get("attributes"),
                "status": e.get("status"),
                "observed_at": e.get("observed_at"),
            })
        finished_at = _iso_z()
        duration_ms = int((time.time() - t0) * 1000)
        # finalize op status
        ops = _load("pg_operations.json")
        for o in ops:
            if o.get("id") == op_row["id"]:
                o["status"] = "succeeded"
                o["finished_at"] = finished_at
                o["duration_ms"] = duration_ms
                o["updated_at"] = now
                break
        _save("pg_operations.json", ops)
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"triggers": rows, "count": len(rows), "operation_id": op_row["id"]}, rows_returned=len(rows), warnings=warnings)
        return {"operation": op_row, "result": {"triggers": rows, "count": len(rows)}}

    if operation == "create":
        # uniqueness key: connection_id + object_identity
        obj_identity = f"{eff_schema}.{tableName}.{triggerName}"
        existing = None
        for e in cache:
            if e.get("connection_id") == conn_row["id"] and e.get("object_identity") == obj_identity and e.get("object_type") == "trigger" and e.get("status") != "deleted":
                existing = e
                break
        if existing and not params_obj.get("replace"):
            # fail
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "CONFLICT"
                    o["error_message"] = "Trigger already exists"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
            return _err("CONFLICT", "Trigger already exists", object_identity=obj_identity)

        # upsert cache entry
        if existing is None:
            entry = {
                "id": _new_id("pgm"),
                "connection_id": conn_row["id"],
                "schema": eff_schema,
                "object_type": "trigger",
                "object_name": triggerName,
                "object_identity": obj_identity,
                "definition": None,
                "comment": None,
                "attributes": {},
                "observed_at": now,
                "status": "current",
                "created_at": now,
                "updated_at": now,
            }
            cache.append(entry)
        else:
            entry = existing
            entry["updated_at"] = now
            entry["observed_at"] = now
            entry["status"] = "current"

        # store trigger metadata
        entry["attributes"] = {
            "table": tableName,
            "function": functionName,
            "timing": eff_timing,
            "events": list(eff_events),
            "forEach": eff_for_each,
            "when": when,
            "enabled": True,
        }
        # pseudo definition
        ev_sql = " OR ".join(eff_events)
        when_sql = f" WHEN ({when})" if when else ""
        entry["definition"] = f"CREATE TRIGGER {triggerName} {eff_timing} {ev_sql} ON {eff_schema}.{tableName} FOR EACH {eff_for_each}{when_sql} EXECUTE FUNCTION {functionName}();"

        _save("pg_object_metadata_cache.json", cache)
        changed.append({"object_type": "trigger", "object_identity": obj_identity, "action": "created" if existing is None else "replaced"})
        details.append({"trigger": {"schema": eff_schema, "tableName": tableName, "triggerName": triggerName}, "definition": entry["definition"], "enabled": True})

        _mark_cache_stale(conn_row["id"], {f"{eff_schema}.{tableName}", f"{eff_schema}.{tableName}.{triggerName}"})

    elif operation == "drop":
        obj_identity = f"{eff_schema}.{tableName}.{triggerName}"
        existing = None
        for e in cache:
            if e.get("connection_id") == conn_row["id"] and e.get("object_identity") == obj_identity and e.get("object_type") == "trigger" and e.get("status") != "deleted":
                existing = e
                break
        if existing is None:
            if params_obj.get("ifExists"):
                # idempotent no-op is not allowed to report success without effect -> treat as NOT_FOUND per contract.
                finished_at = _iso_z()
                duration_ms = int((time.time() - t0) * 1000)
                ops = _load("pg_operations.json")
                for o in ops:
                    if o.get("id") == op_row["id"]:
                        o["status"] = "failed"
                        o["finished_at"] = finished_at
                        o["duration_ms"] = duration_ms
                        o["error_code"] = "NOT_FOUND"
                        o["error_message"] = "Trigger not found"
                        o["updated_at"] = now
                        break
                _save("pg_operations.json", ops)
                _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
                return _err("NOT_FOUND", "Trigger not found", object_identity=obj_identity)
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "NOT_FOUND"
                    o["error_message"] = "Trigger not found"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
            return _err("NOT_FOUND", "Trigger not found", object_identity=obj_identity)

        # mark deleted via lifecycle transition current/stale -> deleted
        if existing.get("status") not in ("current", "stale"):
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "INVALID_TRANSITION"
                    o["error_message"] = "Cannot drop trigger from current state"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
            return _err("INVALID_TRANSITION", "Cannot drop trigger from current state", status=existing.get("status"))

        existing["status"] = "deleted"
        existing["updated_at"] = now
        existing["observed_at"] = now
        _save("pg_object_metadata_cache.json", cache)
        changed.append({"object_type": "trigger", "object_identity": obj_identity, "action": "dropped"})
        details.append({"trigger": {"schema": eff_schema, "tableName": tableName, "triggerName": triggerName}, "dropped": True})
        _mark_cache_stale(conn_row["id"], {f"{eff_schema}.{tableName}", obj_identity})

    elif operation == "set_state":
        obj_identity = f"{eff_schema}.{tableName}.{triggerName}"
        existing = None
        for e in cache:
            if e.get("connection_id") == conn_row["id"] and e.get("object_identity") == obj_identity and e.get("object_type") == "trigger" and e.get("status") != "deleted":
                existing = e
                break
        if existing is None:
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "NOT_FOUND"
                    o["error_message"] = "Trigger not found"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
            return _err("NOT_FOUND", "Trigger not found", object_identity=obj_identity)

        attrs = existing.get("attributes") or {}
        prev = attrs.get("enabled")
        if prev is True and enable is True:
            # No success without effect
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "CONFLICT"
                    o["error_message"] = "Trigger already enabled"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
            return _err("CONFLICT", "Trigger already enabled", object_identity=obj_identity)
        if prev is False and enable is False:
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "CONFLICT"
                    o["error_message"] = "Trigger already disabled"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
            return _err("CONFLICT", "Trigger already disabled", object_identity=obj_identity)

        attrs["enabled"] = bool(enable)
        existing["attributes"] = attrs
        existing["updated_at"] = now
        existing["observed_at"] = now
        if existing.get("status") == "stale":
            existing["status"] = "current"
        _save("pg_object_metadata_cache.json", cache)

        changed.append({"object_type": "trigger", "object_identity": obj_identity, "action": "enabled" if enable else "disabled"})
        details.append({"trigger": {"schema": eff_schema, "tableName": tableName, "triggerName": triggerName}, "enabled": bool(enable)})
        _mark_cache_stale(conn_row["id"], {f"{eff_schema}.{tableName}", obj_identity})

    # finalize op
    finished_at = _iso_z()
    duration_ms = int((time.time() - t0) * 1000)
    ops = _load("pg_operations.json")
    for o in ops:
        if o.get("id") == op_row["id"]:
            o["status"] = "succeeded"
            o["finished_at"] = finished_at
            o["duration_ms"] = duration_ms
            o["updated_at"] = now
            break
    _save("pg_operations.json", ops)
    _upsert_result(op_row["id"], "execution_summary", "json", content_json={"changed": changed, "details": details, "operation_id": op_row["id"]}, rows_affected=len(changed), warnings=warnings)
    return {"operation": op_row, "result": {"changed": changed, "details": details}}

def pg_manage_indexes(operation, connectionString=None, schema=None, tableName=None, indexName=None, includeStats=None, columns=None, unique=None, concurrent=None, method=None, where=None, ifNotExists=None, ifExists=None, cascade=None, target=None, type=None, minSizeBytes=None, showUnused=None, showDuplicates=None, **_extra):
    import json, os, datetime, time, hashlib, re, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _iso_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _redact_dsn(dsn):
        if not isinstance(dsn, str) or not dsn:
            return None
        s = dsn.strip()
        s = re.sub(r"(?i)\bpassword\s*=\s*[^ \t\r\n]+", "password=REDACTED", s)
        s = re.sub(r":([^:@/]+)@", ":REDACTED@", s)
        return s

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time())+os.urandom(8).hex()).encode()).hexdigest()[:24]}"

    def _type_err(name, kind):
        return _err("VALIDATION_ERROR", f"{name} must be {kind}")

    def _find_or_create_connection(dsn):
        conns = _load("pg_connections.json")
        if dsn is None:
            for c in conns:
                if c.get("status") == "active":
                    return c, conns, False
            return None, conns, False
        if not isinstance(dsn, str) or not dsn.strip():
            return _err("VALIDATION_ERROR", "connectionString must be a non-empty string"), conns, False
        red = _redact_dsn(dsn)
        for c in conns:
            if c.get("connection_string_redacted") == red and c.get("status") != "deleted":
                return c, conns, False
        row = {
            "id": _new_id("pgc"),
            "display_name": None,
            "connection_string_redacted": red,
            "connection_string_secret_ref": None,
            "host": None,
            "port": None,
            "database_name": None,
            "username": None,
            "ssl_mode": None,
            "status": "active",
            "last_tested_at": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now,
        }
        conns.append(row)
        return row, conns, True

    def _log_op(group, requested_op, conn_id, params_obj, status, error_code=None, error_message=None, started_at=None, finished_at=None, duration_ms=None):
        ops = _load("pg_operations.json")
        oid = _new_id("pgo")
        row = {
            "id": oid,
            "tool_name": "pg_manage_indexes",
            "connection_id": conn_id,
            "source_connection_id": None,
            "target_connection_id": None,
            "operation_group": group,
            "requested_operation": requested_op,
            "params": params_obj,
            "params_hash": hashlib.sha256(json.dumps(params_obj, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest(),
            "status": status,
            "started_at": started_at,
            "finished_at": finished_at,
            "duration_ms": duration_ms,
            "error_code": error_code,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(row)
        _save("pg_operations.json", ops)
        return row

    def _upsert_result(operation_id, result_type, content_format, content_json=None, content_text=None, external_blob_ref=None, rows_returned=None, rows_affected=None, warnings=None):
        if warnings is None:
            warnings = []
        results = _load("pg_operation_results.json")
        existing = None
        for r in results:
            if r.get("operation_id") == operation_id and r.get("result_type") == result_type:
                existing = r
                break
        if existing is None:
            row = {
                "id": _new_id("pgor"),
                "operation_id": operation_id,
                "result_type": result_type,
                "content_format": content_format,
                "content_json": content_json,
                "content_text": content_text,
                "external_blob_ref": external_blob_ref,
                "rows_returned": rows_returned,
                "rows_affected": rows_affected,
                "warnings": warnings if isinstance(warnings, list) else [],
                "created_at": now,
                "updated_at": now,
            }
            results.append(row)
        else:
            existing["content_format"] = content_format
            existing["content_json"] = content_json
            existing["content_text"] = content_text
            existing["external_blob_ref"] = external_blob_ref
            existing["rows_returned"] = rows_returned
            existing["rows_affected"] = rows_affected
            existing["warnings"] = warnings if isinstance(warnings, list) else []
            existing["updated_at"] = now
        _save("pg_operation_results.json", results)

    def _mark_cache_stale(connection_id, object_identities):
        cache = _load("pg_object_metadata_cache.json")
        changed = 0
        for e in cache:
            if e.get("connection_id") != connection_id:
                continue
            if e.get("object_identity") in object_identities and e.get("status") in ("current", "stale"):
                if e.get("status") != "stale":
                    e["status"] = "stale"
                    e["updated_at"] = now
                    changed += 1
        if changed:
            _save("pg_object_metadata_cache.json", cache)

    # Validate basic types
    if operation not in ("get", "create", "drop", "reindex", "analyze_usage"):
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": schema, "tableName": tableName, "indexName": indexName,
                      "includeStats": includeStats, "columns": columns, "unique": unique, "concurrent": concurrent, "method": method, "where": where,
                      "ifNotExists": ifNotExists, "ifExists": ifExists, "cascade": cascade, "target": target, "type": type,
                      "minSizeBytes": minSizeBytes, "showUnused": showUnused, "showDuplicates": showDuplicates}
        op_row = _log_op("schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message="Invalid operation")
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
        return _err("VALIDATION_ERROR", "operation must be one of get/create/drop/reindex/analyze_usage")

    if connectionString is not None and not isinstance(connectionString, str):
        params_obj = {"operation": operation, "connectionString": None, "schema": schema, "tableName": tableName, "indexName": indexName,
