    for name, v in (("schema", schema), ("tableName", tableName), ("indexName", indexName), ("method", method), ("where", where), ("target", target), ("type", type)):
        if v is not None and not isinstance(v, str):
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": schema if schema is not None else "public",
