    for name, v in (("includeStats", includeStats), ("unique", unique), ("concurrent", concurrent), ("ifNotExists", ifNotExists), ("ifExists", ifExists), ("cascade", cascade), ("showUnused", showUnused), ("showDuplicates", showDuplicates)):
        if v is not None and not isinstance(v, bool):
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": schema if schema is not None else "public",
                          "tableName": tableName, "indexName": indexName, "includeStats": includeStats, "columns": columns, "unique": unique,
