            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _type_err(name, "a boolean")

    if columns is not None:
        if not isinstance(columns, list) or any(not isinstance(c, str) for c in columns) or len(columns) == 0:
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": schema if schema is not None else "public",
                          "tableName": tableName, "indexName": indexName, "includeStats": includeStats, "columns": columns, "unique": unique,
