            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("VALIDATION_ERROR", "columns must be a non-empty array of strings")

    if minSizeBytes is not None and not isinstance(minSizeBytes, (int, float)):
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": schema if schema is not None else "public",
                      "tableName": tableName, "indexName": indexName, "includeStats": includeStats, "columns": columns, "unique": unique,
                      "concurrent": concurrent, "method": method, "where": where, "ifNotExists": ifNotExists, "ifExists": ifExists,
                      "cascade": cascade, "target": target, "type": type, "minSizeBytes": minSizeBytes, "showUnused": showUnused, "showDuplicates": showDuplicates}
        op_row = _log_op("schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message="minSizeBytes must be a number")
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
        return _type_err("minSizeBytes", "a number")

    eff_schema = schema if schema is not None else "public"
    eff_method = method if method is not None else "btree"
    if eff_method not in ("btree", "hash", "gist", "spgist", "gin", "brin"):
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema,
                      "tableName": tableName, "indexName": indexName, "includeStats": includeStats, "columns": columns, "unique": unique,
                      "concurrent": concurrent, "method": eff_method, "where": where, "ifNotExists": ifNotExists, "ifExists": ifExists,
