        op_row = _log_op("schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message="Invalid method")
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
        return _err("VALIDATION_ERROR", "method must be one of btree/hash/gist/spgist/gin/brin")

    # op-specific required
    if operation == "create":
        if not tableName:
            msg = "tableName is required for create"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName, "indexName": indexName,
                          "includeStats": includeStats, "columns": columns, "unique": unique, "concurrent": concurrent, "method": eff_method, "where": where,
                          "ifNotExists": ifNotExists, "ifExists": ifExists, "cascade": cascade, "target": target, "type": type,
