            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("VALIDATION_ERROR", msg)
        if not indexName:
            msg = "indexName is required for create"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName, "indexName": indexName,
                          "includeStats": includeStats, "columns": columns, "unique": unique, "concurrent": concurrent, "method": eff_method, "where": where,
                          "ifNotExists": ifNotExists, "ifExists": ifExists, "cascade": cascade, "target": target, "type": type,
                          "minSizeBytes": minSizeBytes, "showUnused": showUnused, "showDuplicates": showDuplicates}
            op_row = _log_op("schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("VALIDATION_ERROR", msg)
        if columns is None:
            msg = "columns is required for create"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName, "indexName": indexName,
                          "includeStats": includeStats, "columns": columns, "unique": unique, "concurrent": concurrent, "method": eff_method, "where": where,
                          "ifNotExists": ifNotExists, "ifExists": ifExists, "cascade": cascade, "target": target, "type": type,
                          "minSizeBytes": minSizeBytes, "showUnused": showUnused, "showDuplicates": showDuplicates}
            op_row = _log_op("schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("VALIDATION_ERROR", msg)

    if operation in ("drop",):
        if not indexName:
            msg = "indexName is required for drop"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName, "indexName": indexName,
                          "includeStats": includeStats, "columns": columns, "unique": unique, "concurrent": concurrent, "method": eff_method, "where": where,
                          "ifNotExists": ifNotExists, "ifExists": ifExists, "cascade": cascade, "target": target, "type": type,
                          "minSizeBytes": minSizeBytes, "showUnused": showUnused, "showDuplicates": showDuplicates}
            op_row = _log_op("schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("VALIDATION_ERROR", msg)

    if operation == "reindex":
        if not target or not type:
            msg = "target and type are required for reindex"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName, "indexName": indexName,
                          "includeStats": includeStats, "columns": columns, "unique": unique, "concurrent": concurrent, "method": eff_method, "where": where,
                          "ifNotExists": ifNotExists, "ifExists": ifExists, "cascade": cascade, "target": target, "type": type,
                          "minSizeBytes": minSizeBytes, "showUnused": showUnused, "showDuplicates": showDuplicates}
            op_row = _log_op("schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("VALIDATION_ERROR", msg)
        if type not in ("index", "table", "schema", "database"):
            msg = "type must be one of index/table/schema/database"
            params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName, "indexName": indexName,
                          "includeStats": includeStats, "columns": columns, "unique": unique, "concurrent": concurrent, "method": eff_method, "where": where,
                          "ifNotExists": ifNotExists, "ifExists": ifExists, "cascade": cascade, "target": target, "type": type,
                          "minSizeBytes": minSizeBytes, "showUnused": showUnused, "showDuplicates": showDuplicates}
            op_row = _log_op("schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=msg)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("VALIDATION_ERROR", msg)

    # Resolve connection
    conn_row, conns, created = _find_or_create_connection(connectionString)
    if isinstance(conn_row, dict) and "error" in conn_row:
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName, "indexName": indexName,
                      "includeStats": includeStats, "columns": columns, "unique": unique, "concurrent": concurrent, "method": eff_method, "where": where,
                      "ifNotExists": ifNotExists, "ifExists": ifExists, "cascade": cascade, "target": target, "type": type,
                      "minSizeBytes": minSizeBytes, "showUnused": showUnused, "showDuplicates": showDuplicates}
        op_row = _log_op("schema", operation, None, params_obj, "failed", error_code="VALIDATION_ERROR", error_message=conn_row["error"]["message"])
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
        return conn_row
    if conn_row is None:
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName, "indexName": indexName,
                      "includeStats": includeStats, "columns": columns, "unique": unique, "concurrent": concurrent, "method": eff_method, "where": where,
                      "ifNotExists": ifNotExists, "ifExists": ifExists, "cascade": cascade, "target": target, "type": type,
                      "minSizeBytes": minSizeBytes, "showUnused": showUnused, "showDuplicates": showDuplicates}
        op_row = _log_op("schema", operation, None, params_obj, "failed", error_code="UNAUTHORIZED", error_message="No active connection available")
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
        return _err("UNAUTHORIZED", "No active connection available")
    if conn_row.get("status") != "active":
        params_obj = {"operation": operation, "connectionString": _redact_dsn(connectionString), "schema": eff_schema, "tableName": tableName, "indexName": indexName,
                      "includeStats": includeStats, "columns": columns, "unique": unique, "concurrent": concurrent, "method": eff_method, "where": where,
                      "ifNotExists": ifNotExists, "ifExists": ifExists, "cascade": cascade, "target": target, "type": type,
                      "minSizeBytes": minSizeBytes, "showUnused": showUnused, "showDuplicates": showDuplicates}
