        "connectionString": _redact_dsn(connectionString),
        "schema": eff_schema,
        "tableName": tableName,
        "indexName": indexName,
        "includeStats": includeStats if includeStats is not None else False,
        "columns": columns,
        "unique": unique if unique is not None else False,
        "concurrent": concurrent if concurrent is not None else False,
        "method": eff_method,
