        "type": type,
        "minSizeBytes": minSizeBytes,
        "showUnused": showUnused if showUnused is not None else True,
        "showDuplicates": showDuplicates if showDuplicates is not None else True,
    }

    started_at = _iso_z()
    op_row = _log_op("schema", operation, conn_row["id"], params_obj, "running", started_at=started_at)

    cache = _load("pg_object_metadata_cache.json")
    warnings = []
    changed = []
    details = []

    def _index_identity(sch, idx):
        return f"{sch}.{idx}"

    def _table_identity(sch, tbl):
        return f"{sch}.{tbl}"

    def _find_indexes():
        out = []
        for e in cache:
            if e.get("connection_id") != conn_row["id"]:
                continue
            if e.get("object_type") != "index":
                continue
            if e.get("status") == "deleted":
                continue
            if e.get("schema") != eff_schema:
                continue
            attrs = e.get("attributes") or {}
            if tableName and attrs.get("table") != tableName:
                continue
            if indexName and e.get("object_name") != indexName:
                continue
            out.append(e)
        return out

    if operation == "get":
        rows = []
        for e in _find_indexes():
            attrs = e.get("attributes") or {}
            row = {
                "schema": e.get("schema"),
                "tableName": attrs.get("table"),
                "indexName": e.get("object_name"),
                "definition": e.get("definition"),
                "attributes": attrs,
                "status": e.get("status"),
                "observed_at": e.get("observed_at"),
            }
            if params_obj["includeStats"]:
                # deterministic-ish pseudo stats
                seed = int(hashlib.sha256((e.get("object_identity") or "").encode()).hexdigest()[:8], 16)
                rnd = random.Random(seed)
                row["stats"] = {
                    "idx_scan": rnd.randint(0, 5000),
                    "idx_tup_read": rnd.randint(0, 200000),
                    "idx_tup_fetch": rnd.randint(0, 200000),
                    "estimated_size_bytes": rnd.randint(0, 50_000_000),
                }
            rows.append(row)

        finished_at = _iso_z()
        duration_ms = int((time.time() - t0) * 1000)
        ops = _load("pg_operations.json")
        for o in ops:
            if o.get("id") == op_row["id"]:
                o["status"] = "succeeded"
                o["finished_at"] = finished_at
                o["duration_ms"] = duration_ms
                o["updated_at"] = now
                break
        _save("pg_operations.json", ops)
        _upsert_result(op_row["id"], "schema_info", "json", content_json={"indexes": rows, "count": len(rows), "operation_id": op_row["id"]}, rows_returned=len(rows), warnings=warnings)
        return {"operation": op_row, "result": {"indexes": rows, "count": len(rows)}}

    if operation == "create":
        obj_identity = _index_identity(eff_schema, indexName)
        existing = None
        for e in cache:
            if e.get("connection_id") == conn_row["id"] and e.get("object_type") == "index" and e.get("object_identity") == obj_identity and e.get("status") != "deleted":
                existing = e
                break
        if existing is not None:
            if params_obj["ifNotExists"]:
                # No success without effect
                finished_at = _iso_z()
                duration_ms = int((time.time() - t0) * 1000)
                ops = _load("pg_operations.json")
                for o in ops:
                    if o.get("id") == op_row["id"]:
                        o["status"] = "failed"
                        o["finished_at"] = finished_at
                        o["duration_ms"] = duration_ms
                        o["error_code"] = "CONFLICT"
                        o["error_message"] = "Index already exists"
                        o["updated_at"] = now
                        break
                _save("pg_operations.json", ops)
                _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
                return _err("CONFLICT", "Index already exists", object_identity=obj_identity)
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "CONFLICT"
                    o["error_message"] = "Index already exists"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("CONFLICT", "Index already exists", object_identity=obj_identity)

        entry = {
            "id": _new_id("pgm"),
            "connection_id": conn_row["id"],
            "schema": eff_schema,
            "object_type": "index",
            "object_name": indexName,
            "object_identity": obj_identity,
            "definition": None,
            "comment": None,
            "attributes": {},
            "observed_at": now,
            "status": "current",
            "created_at": now,
            "updated_at": now,
        }
        entry["attributes"] = {
            "table": tableName,
            "columns": list(columns),
            "unique": bool(params_obj["unique"]),
            "method": eff_method,
            "where": where,
            "concurrent": bool(params_obj["concurrent"]),
        }
        uniq = "UNIQUE " if params_obj["unique"] else ""
        conc = "CONCURRENTLY " if params_obj["concurrent"] else ""
        where_sql = f" WHERE {where}" if where else ""
        cols_sql = ", ".join(columns)
        entry["definition"] = f"CREATE {uniq}INDEX {conc}{indexName} ON {eff_schema}.{tableName} USING {eff_method} ({cols_sql}){where_sql};"
        cache.append(entry)
        _save("pg_object_metadata_cache.json", cache)

        changed.append({"object_type": "index", "object_identity": obj_identity, "action": "created"})
        details.append({"index": {"schema": eff_schema, "tableName": tableName, "indexName": indexName}, "definition": entry["definition"]})
        _mark_cache_stale(conn_row["id"], {_table_identity(eff_schema, tableName), obj_identity})

    elif operation == "drop":
        obj_identity = _index_identity(eff_schema, indexName)
        existing = None
        for e in cache:
            if e.get("connection_id") == conn_row["id"] and e.get("object_type") == "index" and e.get("object_identity") == obj_identity and e.get("status") != "deleted":
                existing = e
                break
        if existing is None:
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "NOT_FOUND"
                    o["error_message"] = "Index not found"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("NOT_FOUND", "Index not found", object_identity=obj_identity)

        if existing.get("status") not in ("current", "stale"):
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "INVALID_TRANSITION"
                    o["error_message"] = "Cannot drop index from current state"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("INVALID_TRANSITION", "Cannot drop index from current state", status=existing.get("status"))

        existing["status"] = "deleted"
        existing["updated_at"] = now
        existing["observed_at"] = now
        _save("pg_object_metadata_cache.json", cache)

        changed.append({"object_type": "index", "object_identity": obj_identity, "action": "dropped"})
        details.append({"index": {"schema": eff_schema, "indexName": indexName}, "dropped": True})
        tbl = (existing.get("attributes") or {}).get("table")
        stale_set = {obj_identity}
        if tbl:
            stale_set.add(_table_identity(eff_schema, tbl))
        _mark_cache_stale(conn_row["id"], stale_set)

    elif operation == "reindex":
        # mark relevant cache stale / updated
        affected = set()
        if type == "index":
            affected.add(_index_identity(eff_schema, target) if "." not in target else target)
        elif type == "table":
            affected.add(_table_identity(eff_schema, target) if "." not in target else target)
        elif type == "schema":
            # all indexes in schema
            for e in cache:
                if e.get("connection_id") == conn_row["id"] and e.get("object_type") == "index" and e.get("schema") == eff_schema and e.get("status") != "deleted":
                    affected.add(e.get("object_identity"))
        elif type == "database":
            for e in cache:
                if e.get("connection_id") == conn_row["id"] and e.get("object_type") == "index" and e.get("status") != "deleted":
                    affected.add(e.get("object_identity"))

        if not affected:
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "NOT_FOUND"
                    o["error_message"] = "Reindex target not found in cache"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", "json", content_json={"changed": [], "details": [], "operation_id": op_row["id"]})
            return _err("NOT_FOUND", "Reindex target not found in cache", target=target, type=type)

        _mark_cache_stale(conn_row["id"], affected)
        changed.append({"action": "reindex", "type": type, "target": target, "affected_count": len(affected)})
        details.append({"reindex": {"type": type, "target": target, "affected": sorted([a for a in affected if a])}})

    elif operation == "analyze_usage":
        # pseudo usage analysis based on cached index entries
        idxs = _find_indexes()
        min_sz = float(minSizeBytes) if minSizeBytes is not None else 0.0
        show_unused = True if showUnused is None else bool(showUnused)
        show_dups = True if showDuplicates is None else bool(showDuplicates)

        findings = {"unused": [], "duplicates": []}
        # compute pseudo size and scans deterministically
        idx_info = []
        for e in idxs:
            ident = e.get("object_identity") or ""
            seed = int(hashlib.sha256(ident.encode()).hexdigest()[:8], 16)
            rnd = random.Random(seed)
            size_b = rnd.randint(0, 100_000_000)
            scans = rnd.randint(0, 2000)
            attrs = e.get("attributes") or {}
            idx_info.append((e, size_b, scans, attrs))

        if show_unused:
            for e, size_b, scans, attrs in idx_info:
                if size_b < min_sz:
                    continue
                if scans == 0:
                    findings["unused"].append({
                        "object_identity": e.get("object_identity"),
                        "indexName": e.get("object_name"),
                        "tableName": attrs.get("table"),
                        "estimated_size_bytes": size_b,
                        "idx_scan": scans,
                        "reason": "idx_scan=0",
                    })

        if show_dups:
            # detect duplicates by same table + same columns + same where + same method + unique
            sig_map = {}
            for e, size_b, scans, attrs in idx_info:
                if size_b < min_sz:
                    continue
                sig = (
                    attrs.get("table"),
                    tuple((attrs.get("columns") or [])),
                    attrs.get("where"),
                    attrs.get("method"),
                    bool(attrs.get("unique")),
                )
                sig_map.setdefault(sig, []).append((e, size_b, scans))
            for sig, items in sig_map.items():
                if sig[0] is None:
                    continue
                if len(items) > 1:
                    findings["duplicates"].append({
                        "tableName": sig[0],
                        "columns": list(sig[1]),
                        "where": sig[2],
                        "method": sig[3],
                        "unique": sig[4],
                        "indexes": [{"object_identity": it[0].get("object_identity"), "indexName": it[0].get("object_name"), "estimated_size_bytes": it[1], "idx_scan": it[2]} for it in items],
                    })

        finished_at = _iso_z()
        duration_ms = int((time.time() - t0) * 1000)
        ops = _load("pg_operations.json")
        for o in ops:
            if o.get("id") == op_row["id"]:
                o["status"] = "succeeded"
                o["finished_at"] = finished_at
                o["duration_ms"] = duration_ms
                o["updated_at"] = now
                break
        _save("pg_operations.json", ops)
        _upsert_result(op_row["id"], "analysis_report", "json", content_json={"findings": findings, "operation_id": op_row["id"]}, rows_returned=len(idxs), warnings=warnings)
        return {"operation": op_row, "result": {"findings": findings}}

    finished_at = _iso_z()
    duration_ms = int((time.time() - t0) * 1000)
    ops = _load("pg_operations.json")
    for o in ops:
        if o.get("id") == op_row["id"]:
            o["status"] = "succeeded"
            o["finished_at"] = finished_at
            o["duration_ms"] = duration_ms
            o["updated_at"] = now
            break
    _save("pg_operations.json", ops)
    _upsert_result(op_row["id"], "execution_summary", "json", content_json={"changed": changed, "details": details, "operation_id": op_row["id"]}, rows_affected=len(changed), warnings=warnings)
    return {"operation": op_row, "result": {"changed": changed, "details": details}}

def pg_manage_constraints(operation, connectionString=None, schema=None, constraintName=None, tableName=None, constraintType=None, columnNames=None, referencedTable=None, referencedColumns=None, referencedSchema=None, onUpdate=None, onDelete=None, constraintTypeCreate=None, checkExpression=None, deferrable=None, initiallyDeferred=None, ifExists=None, cascade=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")
