        "constraintTypeCreate": constraintTypeCreate,
        "checkExpression": checkExpression,
        "deferrable": deferrable if deferrable is not None else False,
        "initiallyDeferred": initiallyDeferred if initiallyDeferred is not None else False,
        "ifExists": ifExists if ifExists is not None else False,
        "cascade": cascade if cascade is not None else False,
    }

    started_at = _iso_z()
    op_row = _log_op(operation, conn_row["id"], params_obj, "running", started_at=started_at)

    cache = _load("pg_object_metadata_cache.json")
    warnings = []
    changed = []
    details = []

    def _constraint_identity(sch, tbl, cname):
        return f"{sch}.{tbl}.{cname}"

    def _find_constraint(obj_ident):
        for e in cache:
            if e.get("connection_id") == conn_row["id"] and e.get("object_type") == "constraint" and e.get("object_identity") == obj_ident and e.get("status") != "deleted":
                return e
        return None

    if operation == "get":
        rows = []
        for e in cache:
            if e.get("connection_id") != conn_row["id"]:
                continue
            if e.get("object_type") != "constraint" or e.get("status") == "deleted":
                continue
            if e.get("schema") != eff_schema:
                continue
            attrs = e.get("attributes") or {}
            if tableName and attrs.get("table") != tableName:
                continue
            if constraintType and attrs.get("constraintType") != constraintType:
                continue
            rows.append({
                "schema": e.get("schema"),
                "tableName": attrs.get("table"),
                "constraintName": e.get("object_name"),
                "constraintType": attrs.get("constraintType"),
                "definition": e.get("definition"),
                "attributes": attrs,
                "status": e.get("status"),
                "observed_at": e.get("observed_at"),
            })

        finished_at = _iso_z()
        duration_ms = int((time.time() - t0) * 1000)
        ops = _load("pg_operations.json")
        for o in ops:
            if o.get("id") == op_row["id"]:
                o["status"] = "succeeded"
                o["finished_at"] = finished_at
                o["duration_ms"] = duration_ms
                o["updated_at"] = now
                break
        _save("pg_operations.json", ops)
        _upsert_result(op_row["id"], "schema_info", {"constraints": rows, "count": len(rows), "operation_id": op_row["id"]}, rows_returned=len(rows), warnings=warnings)
        return {"operation": op_row, "result": {"constraints": rows, "count": len(rows)}}

    if operation in ("create_fk", "create"):
        obj_ident = _constraint_identity(eff_schema, tableName, constraintName)
        existing = _find_constraint(obj_ident)
        if existing is not None:
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "CONFLICT"
                    o["error_message"] = "Constraint already exists"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", {"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
            return _err("CONFLICT", "Constraint already exists", object_identity=obj_ident)

        entry = {
            "id": _new_id("pgm"),
            "connection_id": conn_row["id"],
            "schema": eff_schema,
            "object_type": "constraint",
            "object_name": constraintName,
            "object_identity": obj_ident,
            "definition": None,
            "comment": None,
            "attributes": {},
            "observed_at": now,
            "status": "current",
            "created_at": now,
            "updated_at": now,
        }

        def_clause = ""
        if params_obj["deferrable"]:
            def_clause += " DEFERRABLE"
            if params_obj["initiallyDeferred"]:
                def_clause += " INITIALLY DEFERRED"

        if operation == "create_fk":
            ref_sch = params_obj["referencedSchema"]
            cols_sql = ", ".join(columnNames)
            ref_cols_sql = ", ".join(referencedColumns)
            onupd = f" ON UPDATE {onUpdate}" if onUpdate else ""
            ondel = f" ON DELETE {onDelete}" if onDelete else ""
            entry["attributes"] = {
                "table": tableName,
                "constraintType": "FOREIGN KEY",
                "columns": list(columnNames),
                "referencedSchema": ref_sch,
                "referencedTable": referencedTable,
                "referencedColumns": list(referencedColumns),
                "onUpdate": onUpdate,
                "onDelete": onDelete,
                "deferrable": bool(params_obj["deferrable"]),
                "initiallyDeferred": bool(params_obj["initiallyDeferred"]),
            }
            entry["definition"] = f"ALTER TABLE {eff_schema}.{tableName} ADD CONSTRAINT {constraintName} FOREIGN KEY ({cols_sql}) REFERENCES {ref_sch}.{referencedTable} ({ref_cols_sql}){onupd}{ondel}{def_clause};"
        else:
            # create (unique/check/primary_key)
            ct = constraintTypeCreate
            if ct == "unique":
                cols_sql = ", ".join(columnNames)
                entry["attributes"] = {"table": tableName, "constraintType": "UNIQUE", "columns": list(columnNames),
                                      "deferrable": bool(params_obj["deferrable"]), "initiallyDeferred": bool(params_obj["initiallyDeferred"])}
                entry["definition"] = f"ALTER TABLE {eff_schema}.{tableName} ADD CONSTRAINT {constraintName} UNIQUE ({cols_sql}){def_clause};"
            elif ct == "primary_key":
                cols_sql = ", ".join(columnNames)
                entry["attributes"] = {"table": tableName, "constraintType": "PRIMARY KEY", "columns": list(columnNames),
                                      "deferrable": bool(params_obj["deferrable"]), "initiallyDeferred": bool(params_obj["initiallyDeferred"])}
                entry["definition"] = f"ALTER TABLE {eff_schema}.{tableName} ADD CONSTRAINT {constraintName} PRIMARY KEY ({cols_sql}){def_clause};"
            else:
                entry["attributes"] = {"table": tableName, "constraintType": "CHECK", "checkExpression": checkExpression,
                                      "deferrable": bool(params_obj["deferrable"]), "initiallyDeferred": bool(params_obj["initiallyDeferred"])}
                entry["definition"] = f"ALTER TABLE {eff_schema}.{tableName} ADD CONSTRAINT {constraintName} CHECK ({checkExpression}){def_clause};"

        cache.append(entry)
        _save("pg_object_metadata_cache.json", cache)

        obj_table = f"{eff_schema}.{tableName}"
        changed.append({"object_type": "constraint", "object_identity": obj_ident, "action": "created"})
        details.append({"constraint": {"schema": eff_schema, "tableName": tableName, "constraintName": constraintName}, "definition": entry["definition"]})
        _mark_cache_stale(conn_row["id"], {obj_table, obj_ident})

    elif operation in ("drop_fk", "drop"):
        obj_ident = _constraint_identity(eff_schema, tableName, constraintName)
        existing = _find_constraint(obj_ident)
        if existing is None:
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "NOT_FOUND"
                    o["error_message"] = "Constraint not found"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", {"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
            return _err("NOT_FOUND", "Constraint not found", object_identity=obj_ident)

        # drop_fk requires it be a FK
        if operation == "drop_fk":
            if (existing.get("attributes") or {}).get("constraintType") != "FOREIGN KEY":
                finished_at = _iso_z()
                duration_ms = int((time.time() - t0) * 1000)
                ops = _load("pg_operations.json")
                for o in ops:
                    if o.get("id") == op_row["id"]:
                        o["status"] = "failed"
                        o["finished_at"] = finished_at
                        o["duration_ms"] = duration_ms
                        o["error_code"] = "CONFLICT"
                        o["error_message"] = "Constraint is not a foreign key"
                        o["updated_at"] = now
                        break
                _save("pg_operations.json", ops)
                _upsert_result(op_row["id"], "schema_info", {"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
                return _err("CONFLICT", "Constraint is not a foreign key", object_identity=obj_ident)

        if existing.get("status") not in ("current", "stale"):
            finished_at = _iso_z()
            duration_ms = int((time.time() - t0) * 1000)
            ops = _load("pg_operations.json")
            for o in ops:
                if o.get("id") == op_row["id"]:
                    o["status"] = "failed"
                    o["finished_at"] = finished_at
                    o["duration_ms"] = duration_ms
                    o["error_code"] = "INVALID_TRANSITION"
                    o["error_message"] = "Cannot drop constraint from current state"
                    o["updated_at"] = now
                    break
            _save("pg_operations.json", ops)
            _upsert_result(op_row["id"], "schema_info", {"changed": [], "details": [], "operation_id": op_row["id"]}, warnings=warnings)
            return _err("INVALID_TRANSITION", "Cannot drop constraint from current state", status=existing.get("status"))

        existing["status"] = "deleted"
        existing["updated_at"] = now
        existing["observed_at"] = now
        _save("pg_object_metadata_cache.json", cache)

        obj_table = f"{eff_schema}.{tableName}"
        changed.append({"object_type": "constraint", "object_identity": obj_ident, "action": "dropped"})
        details.append({"constraint": {"schema": eff_schema, "tableName": tableName, "constraintName": constraintName}, "dropped": True})
        _mark_cache_stale(conn_row["id"], {obj_table, obj_ident})

    finished_at = _iso_z()
    duration_ms = int((time.time() - t0) * 1000)
    ops = _load("pg_operations.json")
    for o in ops:
        if o.get("id") == op_row["id"]:
            o["status"] = "succeeded"
            o["finished_at"] = finished_at
            o["duration_ms"] = duration_ms
            o["updated_at"] = now
            break
    _save("pg_operations.json", ops)
    _upsert_result(op_row["id"], "execution_summary", {"changed": changed, "details": details, "operation_id": op_row["id"]}, rows_affected=len(changed), warnings=warnings)
    return {"operation": op_row, "result": {"changed": changed, "details": details}}

def pg_manage_rls(operation, connectionString=None, tableName=None, schema=None, policyName=None, using=None, check=None, command=None, role=None, replace=None, roles=None, ifExists=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---------- helpers ----------
    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(os.urandom(16)).hexdigest()[:12]}"

    def _as_bool(x, name):
        if x is None:
            return None
        if isinstance(x, bool):
            return x
        return _err("VALIDATION_ERROR", f"{name} must be a boolean")

    def _is_nonempty_str(x):
        return isinstance(x, str) and len(x.strip()) > 0

    def _validate_ident(x, name):
        # Not strict SQL; just reject obviously unsafe/empty. Allow quotes/dots? tool uses tableName/policyName separately.
        if x is None:
            return None
        if not isinstance(x, str):
            return _err("VALIDATION_ERROR", f"{name} must be a string")
        if not x.strip():
            return _err("VALIDATION_ERROR", f"{name} must not be empty")
        if "\x00" in x:
            return _err("VALIDATION_ERROR", f"{name} contains invalid characters")
        return x.strip()

    def _redact_dsn(dsn):
        if not isinstance(dsn, str):
            return None
        s = dsn.strip()
        if not s:
            return None
        # Redact password=... in keyword DSN
        s = re.sub(r"(?i)\bpassword\s*=\s*('([^']*)'|\"([^\"]*)\"|(\S+))", "password=REDACTED", s)
        # Redact URI password: scheme://user:pass@host/...
        s = re.sub(r"(?i)(://[^:/@\s]+:)([^@/\s]+)(@)", r"\1REDACTED\3", s)
        return s

    def _parse_dsn_min(dsn):
        # Best-effort extraction for indexing; do not fail if can't parse.
        host = port = db = user = ssl = None
        s = dsn.strip()
        # keyword format
        kv = dict(re.findall(r"(\w+)\s*=\s*('([^']*)'|\"([^\"]*)\"|(\S+))", s))
        if kv:
            def _unq(v):
                if v is None:
                    return v
                if len(v) >= 2 and ((v[0] == v[-1] == "'") or (v[0] == v[-1] == '"')):
                    return v[1:-1]
                return v
            host = _unq(kv.get("host"))
            p = _unq(kv.get("port"))
            try:
                port = int(p) if p is not None else None
            except Exception:
                port = None
            db = _unq(kv.get("dbname") or kv.get("database"))
            user = _unq(kv.get("user") or kv.get("username"))
            ssl = _unq(kv.get("sslmode"))
            return host, port, db, user, ssl
        # uri format
        m = re.match(r"(?i)^(postgres(?:ql)?):\/\/([^@\s\/]+@)?([^:\/\s\?]+)?(?::(\d+))?(\/([^?\s]+))?(\?.*)?$", s)
        if m:
            auth = m.group(2)[:-1] if m.group(2) else None
            host = m.group(3)
            try:
                port = int(m.group(4)) if m.group(4) else None
            except Exception:
                port = None
            db = m.group(6) if m.group(6) else None
            if auth:
                # auth like user or user:pass
                user = auth.split(":", 1)[0] if auth else None
            q = m.group(7) or ""
            q_m = re.search(r"(?i)(?:\?|&)sslmode=([^&]+)", q)
            ssl = q_m.group(1) if q_m else None
        return host, port, db, user, ssl

    def _resolve_connection(connectionString_value, connections):
        # If no connectionString provided, choose any active connection profile that exists.
        if connectionString_value is None:
            for c in connections:
                if isinstance(c, dict) and c.get("status") == "active":
                    return c, None, None  # conn, created(False), redacted(None)
            return None, None, None

        if not isinstance(connectionString_value, str) or not connectionString_value.strip():
            return _err("VALIDATION_ERROR", "connectionString must be a non-empty string when provided"), None, None

        red = _redact_dsn(connectionString_value)
        if not red:
            return _err("VALIDATION_ERROR", "connectionString must be a non-empty string"), None, None

        # Find by uniqueness key connection_string_redacted
        for c in connections:
            if isinstance(c, dict) and c.get("connection_string_redacted") == red:
                if c.get("status") == "deleted":
                    return _err("INVALID_TRANSITION", "connection profile is deleted and cannot be used", connection_id=c.get("id")), None, None
                if c.get("status") == "disabled":
                    # Not authorized/usable
                    return _err("UNAUTHORIZED", "connection profile is disabled", connection_id=c.get("id")), None, None
                return c, False, red

        # Create new connection profile
        host, port, db, user, ssl = _parse_dsn_min(connectionString_value)
        if port is not None and not (1 <= port <= 65535):
            return _err("VALIDATION_ERROR", "port must be between 1 and 65535 when present"), None, None

        newc = {
            "id": _new_id("pgc"),
            "display_name": None,
            "connection_string_redacted": red,
            "connection_string_secret_ref": None,
            "host": host,
            "port": port,
            "database_name": db,
            "username": user,
            "ssl_mode": ssl,
            "status": "active",
            "last_tested_at": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now,
        }
        connections.append(newc)
        return newc, True, red

    def _op_group_for(operation_value):
        # RLS is a security control; "get_policies" is a read but still security group.
        return "security"

    def _validate_operation_params(op):
        # Apply defaults
        eff_schema = "public" if schema is None else schema
        v = _validate_ident(eff_schema, "schema")
        if isinstance(v, dict) and v.get("error"):
            return v
        eff_schema = v

        v_table = _validate_ident(tableName, "tableName")
        if isinstance(v_table, dict) and v_table.get("error"):
            return v_table
        v_policy = _validate_ident(policyName, "policyName")
        if isinstance(v_policy, dict) and v_policy.get("error"):
            return v_policy

        eff_replace = _as_bool(replace, "replace")
        if isinstance(eff_replace, dict) and eff_replace.get("error"):
            return eff_replace
        eff_ifExists = _as_bool(ifExists, "ifExists")
        if isinstance(eff_ifExists, dict) and eff_ifExists.get("error"):
            return eff_ifExists

        # roles: array[str]
        eff_roles = None
        if roles is not None:
            if not isinstance(roles, list) or any((not isinstance(r, str) or not r.strip()) for r in roles):
                return _err("VALIDATION_ERROR", "roles must be an array of non-empty strings")
            eff_roles = [r.strip() for r in roles]

        # command enum
        eff_command = command
        if eff_command is not None:
            if not isinstance(eff_command, str):
                return _err("VALIDATION_ERROR", "command must be a string")
            if eff_command not in ["ALL", "SELECT", "INSERT", "UPDATE", "DELETE"]:
                return _err("VALIDATION_ERROR", "command must be one of ALL, SELECT, INSERT, UPDATE, DELETE")

        # role for create_policy
        eff_role = role
        if eff_role is not None:
            v = _validate_ident(eff_role, "role")
            if isinstance(v, dict) and v.get("error"):
                return v
            eff_role = v

        # using/check are expressions; accept non-empty strings when required.
        eff_using = using
        if eff_using is not None and (not isinstance(eff_using, str) or not eff_using.strip()):
            return _err("VALIDATION_ERROR", "using must be a non-empty string when provided")
        if eff_using is not None:
            eff_using = eff_using.strip()
        eff_check = check
        if eff_check is not None and (not isinstance(eff_check, str) or not eff_check.strip()):
            return _err("VALIDATION_ERROR", "check must be a non-empty string when provided")
        if eff_check is not None:
            eff_check = eff_check.strip()

        if op in ["enable", "disable"]:
            if v_table is None:
                return _err("VALIDATION_ERROR", "tableName is required for enable/disable")
        elif op in ["create_policy", "edit_policy", "drop_policy"]:
            if v_table is None:
                return _err("VALIDATION_ERROR", "tableName is required for create_policy/edit_policy/drop_policy")
            if v_policy is None:
                return _err("VALIDATION_ERROR", "policyName is required for create_policy/edit_policy/drop_policy")
            if op == "create_policy":
                if eff_using is None:
                    return _err("VALIDATION_ERROR", "using is required for create_policy")
        elif op == "get_policies":
            # optional tableName as filter
            pass
        else:
            return _err("VALIDATION_ERROR", "invalid operation")

        return {
            "schema": eff_schema,
            "tableName": v_table,
            "policyName": v_policy,
            "using": eff_using,
            "check": eff_check,
            "command": eff_command,
            "role": eff_role,
            "replace": eff_replace if eff_replace is not None else False,
            "roles": eff_roles,
            "ifExists": eff_ifExists if eff_ifExists is not None else False,
        }

    def _mark_cache_stale(cache, connection_id, identities):
        changed = 0
        for row in cache:
            if not isinstance(row, dict):
                continue
            if row.get("connection_id") != connection_id:
                continue
            if row.get("object_identity") in identities and row.get("status") in ("current", "stale"):
                if row.get("status") != "stale":
                    row["status"] = "stale"
                    row["updated_at"] = now
                    changed += 1
        return changed

    # ---------- validate primary inputs ----------
    if not isinstance(operation, str):
        return _err("VALIDATION_ERROR", "operation must be a string")
    if operation not in ["enable", "disable", "create_policy", "edit_policy", "drop_policy", "get_policies"]:
        return _err("VALIDATION_ERROR", "operation must be one of enable, disable, create_policy, edit_policy, drop_policy, get_policies")

    validated = _validate_operation_params(operation)
    if isinstance(validated, dict) and validated.get("error"):
        return validated

    # ---------- load store ----------
    connections = _load("pg_connections.json")
    operations = _load("pg_operations.json")
    results = _load("pg_operation_results.json")
    jobs = _load("pg_data_transfer_jobs.json")
    cache = _load("pg_object_metadata_cache.json")

    # ---------- resolve connection context (ambient auth) ----------
    resolved = _resolve_connection(connectionString, connections)
    if isinstance(resolved, tuple):
        conn, created_conn, red = resolved
    else:
        # error dict
        conn = resolved
        created_conn = None
        red = None

    if isinstance(conn, dict) and conn.get("error"):
        # Still must log an operation? business rules say every tool invocation MUST create exactly one pg_operations row
        # with validated params. If validation already passed, we can create a failed op even if unauthorized.
        pass
    elif conn is None:
        # No usable connection in store and no connectionString provided.
        # Create operation row (failed) with no connection_id per schema (nullable) but tool needs a DB: treat as UNAUTHORIZED.
        pass

    # Build effective params to persist (include defaults)
    eff_params = {
        "connectionString": _redact_dsn(connectionString) if connectionString is not None else None,
        "operation": operation,
        "tableName": validated["tableName"],
        "schema": validated["schema"],
        "policyName": validated["policyName"],
        "using": validated["using"],
        "check": validated["check"],
        "command": validated["command"],
        "role": validated["role"],
        "replace": validated["replace"],
        "roles": validated["roles"],
        "ifExists": validated["ifExists"],
    }

    # ---------- create operation row (always exactly one) ----------
    op_id = _new_id("pgo")
    op_row = {
        "id": op_id,
        "tool_name": "pg_manage_rls",
        "connection_id": None,
        "source_connection_id": None,
        "target_connection_id": None,
        "operation_group": _op_group_for(operation),
        "requested_operation": operation,
        "params": eff_params,
        "params_hash": hashlib.sha256(json.dumps(eff_params, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest(),
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    if isinstance(conn, dict) and not conn.get("error"):
        op_row["connection_id"] = conn.get("id")

    operations.append(op_row)

    # ---------- execute "simulated" backend behavior and store result ----------
    # This server is offline; it records intent and updates cache/metadata store to reflect requested changes.
    # We'll treat get_policies as a read against metadata cache entries of type rls_policy.
    status = "succeeded"
    err_obj = None
    summary = {"operation": operation, "changes": []}
    warnings = []

    # Determine auth outcome after op row created.
    if conn is None:
        status = "failed"
        op_row["error_code"] = "NO_ACTIVE_CONNECTION"
        op_row["error_message"] = "No active connection available; provide connectionString or create an active connection profile."
        err_obj = _err("UNAUTHORIZED", op_row["error_message"])
    elif isinstance(conn, dict) and conn.get("error"):
        status = "failed"
        op_row["error_code"] = "CONNECTION_UNUSABLE"
        op_row["error_message"] = conn["error"]["message"]
        err_obj = conn
    else:
        connection_id = conn["id"]
        sch = validated["schema"]
        tbl = validated["tableName"]
        pol = validated["policyName"]

        # object identities we may touch
        table_ident = f"{sch}.{tbl}" if tbl else None
        policy_ident = f"{sch}.{tbl}.policy:{pol}" if (tbl and pol) else None

        # Find existing cache entries
        def _find_cache(object_identity):
            for row in cache:
                if isinstance(row, dict) and row.get("connection_id") == connection_id and row.get("object_identity") == object_identity:
                    return row
            return None

        if operation == "get_policies":
            # Filter current+stale (not deleted)
            matched = []
            for row in cache:
                if not isinstance(row, dict):
                    continue
                if row.get("connection_id") != connection_id:
                    continue
                if row.get("object_type") != "rls_policy":
                    continue
                if row.get("status") == "deleted":
                    continue
                if tbl:
                    if row.get("schema") != sch:
                        continue
                    # policy entries attribute table_identity or object_identity prefix; use object_identity convention used here
                    if not str(row.get("object_identity", "")).startswith(f"{sch}.{tbl}.policy:"):
                        continue
                matched.append(row)

            content = {
                "policies": matched,
                "filter": {"schema": sch, "tableName": tbl},
                "total": len(matched),
            }
            res_type = "schema_info"
            res_row = {
                "id": _new_id("pgr"),
                "operation_id": op_id,
                "result_type": res_type,
                "content_format": "json",
                "content_json": content,
                "content_text": None,
                "external_blob_ref": None,
                "rows_returned": len(matched),
                "rows_affected": None,
                "warnings": warnings,
                "created_at": now,
                "updated_at": now,
            }
            results.append(res_row)
            summary["changes"].append({"read_policies": len(matched)})

        elif operation in ("enable", "disable"):
            # Update/create a table cache entry to reflect RLS enabled state, then mark stale.
            # We treat this as a mutating schema/security operation and produce an execution_summary.
            existing_table = _find_cache(table_ident)
            if existing_table is None:
                # Create a minimal table cache entry to store rls_enabled attribute.
                new_row = {
                    "id": _new_id("pgm"),
                    "connection_id": connection_id,
                    "schema": sch,
                    "object_type": "table",
                    "object_name": tbl,
                    "object_identity": table_ident,
                    "definition": None,
                    "comment": None,
                    "attributes": {"rls_enabled": (operation == "enable")},
                    "observed_at": now,
                    "status": "current",
                    "created_at": now,
                    "updated_at": now,
                }
                cache.append(new_row)
                summary["changes"].append({"object": table_ident, "action": "created_cache", "rls_enabled": operation == "enable"})
            else:
                if existing_table.get("status") == "deleted":
                    status = "failed"
                    op_row["error_code"] = "OBJECT_DELETED"
                    op_row["error_message"] = f"Table cache entry is deleted: {table_ident}"
                    err_obj = _err("NOT_FOUND", op_row["error_message"])
                else:
                    attrs = existing_table.get("attributes")
                    if not isinstance(attrs, dict):
                        attrs = {}
                    attrs["rls_enabled"] = (operation == "enable")
                    existing_table["attributes"] = attrs
                    existing_table["observed_at"] = now
                    # keep as current since we "observed" it; but business rule says affected entries marked stale OR updated.
                    existing_table["status"] = "current"
                    existing_table["updated_at"] = now
                    summary["changes"].append({"object": table_ident, "action": "set_rls", "rls_enabled": operation == "enable"})

            if err_obj is None:
                # Mark related policy entries stale since table RLS changed.
                stale_count = _mark_cache_stale(cache, connection_id, set([x.get("object_identity") for x in cache if isinstance(x, dict) and str(x.get("object_identity", "")).startswith(f"{sch}.{tbl}.policy:")]))
                if stale_count:
                    summary["changes"].append({"object": table_ident, "action": "marked_policies_stale", "count": stale_count})

                res_row = {
                    "id": _new_id("pgr"),
                    "operation_id": op_id,
                    "result_type": "execution_summary",
                    "content_format": "json",
                    "content_json": {"summary": summary},
                    "content_text": None,
                    "external_blob_ref": None,
                    "rows_returned": None,
                    "rows_affected": 1,
                    "warnings": warnings,
                    "created_at": now,
                    "updated_at": now,
                }
                results.append(res_row)

        elif operation == "create_policy":
            # If exists and replace false => conflict. If replace true => overwrite.
            existing_policy = _find_cache(policy_ident)
            if existing_policy is not None and existing_policy.get("status") != "deleted" and not validated["replace"]:
                status = "failed"
                op_row["error_code"] = "POLICY_EXISTS"
                op_row["error_message"] = f"Policy already exists: {policy_ident}"
                err_obj = _err("CONFLICT", op_row["error_message"])

            if err_obj is None:
                attrs = {
                    "table_identity": table_ident,
                    "command": validated["command"] or "ALL",
                    "role": validated["role"],
                    "roles": None,
                    "using": validated["using"],
                    "check": validated["check"],
                }
                if existing_policy is None or existing_policy.get("status") == "deleted":
                    new_row = {
                        "id": _new_id("pgm"),
                        "connection_id": connection_id,
                        "schema": sch,
                        "object_type": "rls_policy",
                        "object_name": pol,
                        "object_identity": policy_ident,
                        "definition": None,
                        "comment": None,
                        "attributes": attrs,
                        "observed_at": now,
                        "status": "current",
                        "created_at": now,
                        "updated_at": now,
                    }
                    cache.append(new_row)
                    summary["changes"].append({"object": policy_ident, "action": "created"})
                else:
                    existing_policy["attributes"] = attrs
                    existing_policy["observed_at"] = now
                    existing_policy["status"] = "current"
                    existing_policy["updated_at"] = now
                    summary["changes"].append({"object": policy_ident, "action": "replaced"})

                _mark_cache_stale(cache, connection_id, {table_ident})

                res_row = {
                    "id": _new_id("pgr"),
                    "operation_id": op_id,
                    "result_type": "schema_info",
                    "content_format": "json",
                    "content_json": {"summary": summary, "policy": _find_cache(policy_ident)},
                    "content_text": None,
                    "external_blob_ref": None,
                    "rows_returned": None,
                    "rows_affected": 1,
                    "warnings": warnings,
                    "created_at": now,
                    "updated_at": now,
                }
                results.append(res_row)

        elif operation == "edit_policy":
            existing_policy = _find_cache(policy_ident)
            if existing_policy is None or existing_policy.get("status") == "deleted":
                status = "failed"
                op_row["error_code"] = "POLICY_NOT_FOUND"
                op_row["error_message"] = f"Policy not found: {policy_ident}"
                err_obj = _err("NOT_FOUND", op_row["error_message"])
            else:
                attrs = existing_policy.get("attributes")
                if not isinstance(attrs, dict):
                    attrs = {}
                # Apply edits: using/check optional; roles list optional
                if validated["using"] is not None:
                    attrs["using"] = validated["using"]
                if validated["check"] is not None:
                    attrs["check"] = validated["check"]
                if validated["roles"] is not None:
                    attrs["roles"] = validated["roles"]
                existing_policy["attributes"] = attrs
                existing_policy["observed_at"] = now
                existing_policy["status"] = "current"
                existing_policy["updated_at"] = now
                summary["changes"].append({"object": policy_ident, "action": "edited"})
                _mark_cache_stale(cache, connection_id, {table_ident})
                res_row = {
                    "id": _new_id("pgr"),
                    "operation_id": op_id,
                    "result_type": "schema_info",
                    "content_format": "json",
                    "content_json": {"summary": summary, "policy": existing_policy},
                    "content_text": None,
                    "external_blob_ref": None,
                    "rows_returned": None,
                    "rows_affected": 1,
                    "warnings": warnings,
                    "created_at": now,
                    "updated_at": now,
                }
                results.append(res_row)

        elif operation == "drop_policy":
            existing_policy = _find_cache(policy_ident)
            if existing_policy is None or existing_policy.get("status") == "deleted":
                if validated["ifExists"]:
                    # idempotent success with effect? If it's already absent, vendor likely returns success; but rule says no success without effect.
                    # For IF EXISTS, effect is "no-op but accepted"; however contract here says no success without effect.
                    # We'll treat as NOT_FOUND even with ifExists false/true to satisfy rule, but include hint.
                    status = "failed"
                    op_row["error_code"] = "POLICY_NOT_FOUND"
                    op_row["error_message"] = f"Policy not found: {policy_ident}"
                    err_obj = _err("NOT_FOUND", op_row["error_message"], ifExists=validated["ifExists"])
                else:
                    status = "failed"
                    op_row["error_code"] = "POLICY_NOT_FOUND"
                    op_row["error_message"] = f"Policy not found: {policy_ident}"
                    err_obj = _err("NOT_FOUND", op_row["error_message"])
            else:
                # lifecycle transition current/stale -> deleted allowed by cache lifecycle
                if existing_policy.get("status") not in ("current", "stale"):
                    status = "failed"
                    op_row["error_code"] = "INVALID_CACHE_STATE"
                    op_row["error_message"] = f"Cannot drop policy from state {existing_policy.get('status')}"
                    err_obj = _err("INVALID_TRANSITION", op_row["error_message"])
                else:
                    existing_policy["status"] = "deleted"
                    existing_policy["observed_at"] = now
                    existing_policy["updated_at"] = now
                    summary["changes"].append({"object": policy_ident, "action": "dropped"})
                    _mark_cache_stale(cache, connection_id, {table_ident})
                    res_row = {
                        "id": _new_id("pgr"),
                        "operation_id": op_id,
                        "result_type": "schema_info",
                        "content_format": "json",
                        "content_json": {"summary": summary},
                        "content_text": None,
                        "external_blob_ref": None,
                        "rows_returned": None,
                        "rows_affected": 1,
                        "warnings": warnings,
                        "created_at": now,
                        "updated_at": now,
                    }
                    results.append(res_row)

    # Ensure mutating ops produce a result if succeeded and none created yet
    if err_obj is None and operation in ("create_policy", "edit_policy", "drop_policy", "enable", "disable"):
        # already produced above, but double-check
        if not any(isinstance(r, dict) and r.get("operation_id") == op_id for r in results):
            res_row = {
                "id": _new_id("pgr"),
                "operation_id": op_id,
                "result_type": "execution_summary",
                "content_format": "json",
                "content_json": {"summary": summary},
                "content_text": None,
                "external_blob_ref": None,
                "rows_returned": None,
                "rows_affected": 1,
                "warnings": warnings,
                "created_at": now,
                "updated_at": now,
            }
            results.append(res_row)

    # ---------- finalize operation lifecycle ----------
    # queued -> running -> succeeded/failed
    # transition: queued -> running
    op_row["status"] = "running"
    op_row["started_at"] = now
    op_row["updated_at"] = now

    end_now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    duration_ms = int(max(0, round((time.time() - t0) * 1000)))

    if err_obj is None:
        op_row["status"] = "succeeded"
        op_row["finished_at"] = end_now
        op_row["duration_ms"] = duration_ms
        op_row["updated_at"] = end_now
    else:
        op_row["status"] = "failed"
        op_row["finished_at"] = end_now
        op_row["duration_ms"] = duration_ms
        op_row["updated_at"] = end_now
        if op_row.get("error_code") is None:
            op_row["error_code"] = err_obj["error"]["code"]
        if op_row.get("error_message") is None:
            op_row["error_message"] = err_obj["error"]["message"]

    # ---------- persist ----------
    try:
        _save("pg_connections.json", connections)
        _save("pg_operations.json", operations)
        _save("pg_operation_results.json", results)
        _save("pg_data_transfer_jobs.json", jobs)
        _save("pg_object_metadata_cache.json", cache)
    except Exception as e:
        return _err("CONFLICT", "failed to persist datastore", detail=str(e))

    # ---------- response envelope ----------
    # Return operation and latest result (if any)
    op_out = op_row
    op_results = [r for r in results if isinstance(r, dict) and r.get("operation_id") == op_id]
    op_results.sort(key=lambda r: r.get("created_at") or "")
    body = {"operation": op_out, "results": op_results}

    if err_obj is not None:
        # include operation context
        return {"error": err_obj["error"], "operation": op_out, "results": op_results}
    return body

def pg_manage_users(operation, connectionString=None, username=None, password=None, superuser=None, createdb=None, createrole=None, login=None, replication=None, connectionLimit=None, validUntil=None, inherit=None, ifExists=None, cascade=None, permissions=None, target=None, targetType=None, withGrantOption=None, schema=None, includeSystemRoles=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((str(time.time_ns()) + os.urandom(8).hex()).encode('utf-8')).hexdigest()[:20]}"

    def _redact_connstr(dsn):
        if not isinstance(dsn, str):
            return None
        s = dsn.strip()
        if not s:
            return None
        if re.match(r"^pgconn_[A-Za-z0-9]+$", s):
            return s
        if "://" in s:
            s = re.sub(r"(?i)(postgres(?:ql)?://[^:/@\s]+:)[^@/\s]+@", r"\1****@", s)
        s = re.sub(r"(?i)\bpassword\s*=\s*([^\s;]+)", "password=****", s)
        return s

    def _parse_connstr_for_index(dsn):
        out = {"host": None, "port": None, "database_name": None, "username": None, "ssl_mode": None}
        if not isinstance(dsn, str):
            return out
        s = dsn.strip()
        if not s or re.match(r"^pgconn_[A-Za-z0-9]+$", s):
            return out
        if "://" not in s:
            kv = dict(re.findall(r"(?i)(\w+)\s*=\s*('[^']*'|\"[^\"]*\"|[^\s]+)", s))
            def _stripq(v):
                if v is None:
                    return None
                v = v.strip()
                if (len(v) >= 2) and ((v[0] == v[-1] == "'") or (v[0] == v[-1] == '"')):
                    return v[1:-1]
                return v
            host = _stripq(kv.get("host") or kv.get("hostname"))
            port = _stripq(kv.get("port"))
            dbn = _stripq(kv.get("dbname") or kv.get("database"))
            user = _stripq(kv.get("user") or kv.get("username"))
            sslm = _stripq(kv.get("sslmode"))
            out["host"] = host or None
            if port and str(port).isdigit():
                out["port"] = int(port)
            out["database_name"] = dbn or None
            out["username"] = user or None
            out["ssl_mode"] = sslm or None
            return out
        m = re.match(r"(?is)^(postgres(?:ql)?)(\+[^:]*)?://(.+)$", s)
        if not m:
            return out
        rest = m.group(3)
        if "?" in rest:
            rest, q = rest.split("?", 1)
        else:
            q = ""
        if "/" in rest:
            before, path = rest.split("/", 1)
        else:
            before, path = rest, ""
        auth = None
        hostport = before
        if "@" in before:
            auth, hostport = before.rsplit("@", 1)
        if auth:
            if ":" in auth:
                out["username"] = auth.split(":", 1)[0] or None
            else:
                out["username"] = auth or None
        host = hostport
        port = None
        if hostport.startswith("["):
            m6 = re.match(r"^\[([^\]]+)\](?::(\d+))?$", hostport)
            if m6:
                host = m6.group(1)
                port = int(m6.group(2)) if m6.group(2) else None
        else:
            if ":" in hostport:
                h, p = hostport.rsplit(":", 1)
                if p.isdigit():
                    host, port = h, int(p)
        out["host"] = host or None
        out["port"] = port
        out["database_name"] = path.split("/", 1)[0] if path else None
        if q:
            for part in q.split("&"):
                if "=" in part:
                    k, v = part.split("=", 1)
                    if k.lower() == "sslmode":
                        out["ssl_mode"] = v or None
        return out

    def _resolve_connection(conn_str):
        conns = _load("pg_connections.json")
        if conn_str is None:
            for c in conns:
                if isinstance(c, dict) and c.get("status") == "active":
                    return c, conns, False
            return None, conns, False
        if not isinstance(conn_str, str) or not conn_str.strip():
            return _err("VALIDATION_ERROR", "connectionString must be a non-empty string when provided."), conns, False
        s = conn_str.strip()
        if re.match(r"^pgconn_[A-Za-z0-9]+$", s):
            for c in conns:
                if isinstance(c, dict) and c.get("id") == s and c.get("status") != "deleted":
                    if c.get("status") != "active":
                        return _err("UNAUTHORIZED", "Referenced connection is not active."), conns, False
                    return c, conns, False
            return _err("NOT_FOUND", "connectionString references an unknown connection id."), conns, False
        red = _redact_connstr(s)
        for c in conns:
            if isinstance(c, dict) and c.get("connection_string_redacted") == red and c.get("status") != "deleted":
                if c.get("status") != "active":
                    return _err("UNAUTHORIZED", "Resolved connection profile is not active."), conns, False
                return c, conns, False
        parsed = _parse_connstr_for_index(s)
        port = parsed.get("port")
        if port is not None and not (1 <= int(port) <= 65535):
            return _err("VALIDATION_ERROR", "connectionString contains an invalid port; must be 1..65535."), conns, False
        sslm = parsed.get("ssl_mode")
        if sslm is not None:
            allowed_ssl = {"disable", "allow", "prefer", "require", "verify-ca", "verify-full"}
            if str(sslm) not in allowed_ssl:
                parsed["ssl_mode"] = None
        now = _now()
        newc = {
            "id": _new_id("pgconn"),
            "display_name": None,
            "connection_string_redacted": red,
            "connection_string_secret_ref": None,
            "host": parsed.get("host"),
            "port": parsed.get("port"),
            "database_name": parsed.get("database_name"),
            "username": parsed.get("username"),
            "ssl_mode": parsed.get("ssl_mode"),
            "status": "active",
            "last_tested_at": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now,
        }
        conns.append(newc)
        _save("pg_connections.json", conns)
        return newc, conns, True

    allowed_ops = {"create", "drop", "alter", "grant", "revoke", "get_permissions", "list"}
    if not isinstance(operation, str) or operation not in allowed_ops:
        return _err("VALIDATION_ERROR", "operation must be one of: create, drop, alter, grant, revoke, get_permissions, list.")

    # Validate common types (relaxed on validUntil: accept any string; only validate if looks like date)
    if username is not None and not isinstance(username, str):
        return _err("VALIDATION_ERROR", "username must be a string when provided.")
    if password is not None and not isinstance(password, str):
        return _err("VALIDATION_ERROR", "password must be a string when provided.")
    if connectionLimit is not None and not isinstance(connectionLimit, (int, float)):
        return _err("VALIDATION_ERROR", "connectionLimit must be a number when provided.")
    if validUntil is not None and not isinstance(validUntil, str):
        return _err("VALIDATION_ERROR", "validUntil must be a string when provided.")
    if validUntil is not None and re.match(r"^\d{4}-\d{2}-\d{2}$", validUntil):
        # validate actual calendar date
        try:
            datetime.date.fromisoformat(validUntil)
        except Exception:
            return _err("VALIDATION_ERROR", "validUntil must be a valid date in YYYY-MM-DD when provided in that format.")

    for bname, bval in [
        ("superuser", superuser), ("createdb", createdb), ("createrole", createrole), ("login", login),
        ("replication", replication), ("inherit", inherit), ("ifExists", ifExists), ("cascade", cascade),
        ("withGrantOption", withGrantOption), ("includeSystemRoles", includeSystemRoles),
    ]:
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean when provided.")

    if permissions is not None:
        if not isinstance(permissions, list) or any((not isinstance(p, str)) for p in permissions):
            return _err("VALIDATION_ERROR", "permissions must be an array of strings when provided.")
        allowed_perms = {"SELECT", "INSERT", "UPDATE", "DELETE", "TRUNCATE", "REFERENCES", "TRIGGER", "ALL"}
        for p in permissions:
            if p not in allowed_perms:
                return _err("VALIDATION_ERROR", f"permissions contains invalid value '{p}'.", allowed=sorted(list(allowed_perms)))

    if targetType is not None and targetType not in ("table", "schema", "database", "sequence", "function"):
        return _err("VALIDATION_ERROR", "targetType must be one of: table, schema, database, sequence, function.")

    # Required fields per op
    if operation in ("create", "drop", "alter", "grant", "revoke", "get_permissions") and (not isinstance(username, str) or not username.strip()):
        return _err("VALIDATION_ERROR", f"username is required for operation '{operation}'.")
    if operation == "create" and (password is None or not isinstance(password, str) or not password.strip()):
        # password required by tool schema semantics; store redacted
        return _err("VALIDATION_ERROR", "password is required for create operation.")
    if operation in ("grant", "revoke"):
        if permissions is None or len(permissions) == 0:
            return _err("VALIDATION_ERROR", f"permissions is required for operation '{operation}'.")
        if not isinstance(target, str) or not target.strip():
            return _err("VALIDATION_ERROR", f"target is required for operation '{operation}'.")
        if targetType is None:
            return _err("VALIDATION_ERROR", f"targetType is required for operation '{operation}'.")

    eff_schema = schema if isinstance(schema, str) and schema.strip() else "public"

    resolved, conns, _created = _resolve_connection(connectionString)
    if isinstance(resolved, dict) and "error" in resolved:
        now = _now()
        op_id = _new_id("pgop")
        ops = _load("pg_operations.json")
        err = resolved["error"]
        # secrets redaction
        safe_password = "****" if password is not None else None
        params = {
            "connectionString": connectionString, "operation": operation, "username": username, "password": safe_password,
            "superuser": superuser, "createdb": createdb, "createrole": createrole, "login": login, "replication": replication,
            "connectionLimit": connectionLimit, "validUntil": validUntil, "inherit": inherit, "ifExists": ifExists, "cascade": cascade,
            "permissions": permissions, "target": target, "targetType": targetType, "withGrantOption": withGrantOption,
            "schema": eff_schema, "includeSystemRoles": includeSystemRoles
        }
        ops.append({
            "id": op_id,
            "tool_name": "pg_manage_users",
            "connection_id": None,
            "source_connection_id": None,
            "target_connection_id": None,
            "operation_group": "access" if operation in ("grant", "revoke", "get_permissions") else "security",
            "requested_operation": operation,
            "params": params,
            "params_hash": None,
            "status": "failed",
            "started_at": now,
            "finished_at": now,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": err.get("code"),
            "error_message": err.get("message"),
            "created_at": now,
            "updated_at": now
        })
        _save("pg_operations.json", ops)
        return _err(err.get("code"), err.get("message"), operation_id=op_id)

    if resolved is None:
        now = _now()
        op_id = _new_id("pgop")
        ops = _load("pg_operations.json")
        safe_password = "****" if password is not None else None
        params = {
            "connectionString": connectionString, "operation": operation, "username": username, "password": safe_password,
            "superuser": superuser, "createdb": createdb, "createrole": createrole, "login": login, "replication": replication,
            "connectionLimit": connectionLimit, "validUntil": validUntil, "inherit": inherit, "ifExists": ifExists, "cascade": cascade,
            "permissions": permissions, "target": target, "targetType": targetType, "withGrantOption": withGrantOption,
            "schema": eff_schema, "includeSystemRoles": includeSystemRoles
        }
        ops.append({
            "id": op_id,
            "tool_name": "pg_manage_users",
            "connection_id": None,
            "source_connection_id": None,
            "target_connection_id": None,
            "operation_group": "access" if operation in ("grant", "revoke", "get_permissions") else "security",
            "requested_operation": operation,
            "params": params,
            "params_hash": None,
            "status": "failed",
            "started_at": now,
            "finished_at": now,
            "duration_ms": int((time.time() - t0) * 1000),
            "error_code": "UNAUTHORIZED",
            "error_message": "No active connection available to serve request.",
            "created_at": now,
            "updated_at": now
        })
        _save("pg_operations.json", ops)
        return _err("UNAUTHORIZED", "No active connection available to serve request.", operation_id=op_id)

    # Create operation row (exactly one); redact password in params
    now = _now()
    op_id = _new_id("pgop")
    safe_password = "****" if password is not None else None
    op_group = "access" if operation in ("grant", "revoke", "get_permissions") else "security"
    params = {
        "connectionString": connectionString,
        "operation": operation,
        "username": username,
        "password": safe_password,
        "superuser": superuser,
        "createdb": createdb,
        "createrole": createrole,
        "login": login,
        "replication": replication,
        "connectionLimit": connectionLimit,
        "validUntil": validUntil,
        "inherit": inherit,
        "ifExists": ifExists,
        "cascade": cascade,
        "permissions": permissions,
        "target": target,
        "targetType": targetType,
        "withGrantOption": withGrantOption,
        "schema": eff_schema,
        "includeSystemRoles": includeSystemRoles
    }
    ops = _load("pg_operations.json")
    op_row = {
        "id": op_id,
        "tool_name": "pg_manage_users",
        "connection_id": resolved.get("id"),
        "source_connection_id": None,
        "target_connection_id": None,
        "operation_group": op_group,
        "requested_operation": operation,
        "params": params,
        "params_hash": None,
        "status": "running",
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op_row)
    _save("pg_operations.json", ops)

    # Finish operation + execution_summary (mutating or access change)
    finished = _now()
    duration_ms = int((time.time() - t0) * 1000)
    ops = _load("pg_operations.json")
    for r in ops:
        if isinstance(r, dict) and r.get("id") == op_id:
            r["status"] = "succeeded"
            r["finished_at"] = finished
            r["duration_ms"] = duration_ms
            r["updated_at"] = finished
            break
    _save("pg_operations.json", ops)

    results = _load("pg_operation_results.json")
    res_id = _new_id("pgres")
    changed = operation in ("create", "drop", "alter", "grant", "revoke")
    summary = {
        "operation": operation,
        "username": username,
        "target": target,
        "targetType": targetType,
        "permissions": permissions,
        "schema": eff_schema,
        "changed": changed,
        "note": "User/permission operation recorded; database not contacted in this environment."
    }
    results.append({
        "id": res_id,
        "operation_id": op_id,
        "result_type": "execution_summary",
        "content_format": "json",
        "content_json": summary,
        "content_text": None,
        "external_blob_ref": None,
        "rows_returned": None,
        "rows_affected": 1 if changed else 0,
        "warnings": [],
        "created_at": finished,
        "updated_at": finished
    })
    _save("pg_operation_results.json", results)

    return {"operation": op_row, "result": results[-1]}

def pg_manage_query(operation, connectionString=None, query=None, analyze=None, buffers=None, verbose=None, costs=None, format=None, limit=None, minDuration=None, orderBy=None, includeNormalized=None, minCalls=None, queryPattern=None, queryId=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # validate
    allowed_ops = {"explain","get_slow_queries","get_stats","reset_stats"}
    if not isinstance(operation, str) or operation not in allowed_ops:
        return _err("VALIDATION_ERROR", "Invalid operation.", allowed=sorted(list(allowed_ops)))
    if connectionString is not None and not isinstance(connectionString, str):
        return _err("VALIDATION_ERROR", "connectionString must be a string when provided.")
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string when provided.")

    # defaults
    if analyze is None: analyze = False
    if buffers is None: buffers = False
    if verbose is None: verbose = False
    if costs is None: costs = True
    if format is None: format = "json"
    if limit is None: limit = 10
    if orderBy is None: orderBy = "mean_time"
    if includeNormalized is None: includeNormalized = True

    for bname, bval in [("analyze", analyze), ("buffers", buffers), ("verbose", verbose), ("costs", costs), ("includeNormalized", includeNormalized)]:
        if not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean.")
    if not isinstance(format, str) or format not in {"text","json","xml","yaml"}:
        return _err("VALIDATION_ERROR", "Invalid format.", allowed=["text","json","xml","yaml"])
    if limit is not None and not isinstance(limit, (int, float)):
        return _err("VALIDATION_ERROR", "limit must be a number.")
    if minDuration is not None and not isinstance(minDuration, (int, float)):
        return _err("VALIDATION_ERROR", "minDuration must be a number when provided.")
    if not isinstance(orderBy, str) or orderBy not in {"mean_time","total_time","calls","cache_hit_ratio"}:
        return _err("VALIDATION_ERROR", "Invalid orderBy.", allowed=["mean_time","total_time","calls","cache_hit_ratio"])
    if minCalls is not None and not isinstance(minCalls, (int, float)):
        return _err("VALIDATION_ERROR", "minCalls must be a number when provided.")
    if queryPattern is not None and not isinstance(queryPattern, str):
        return _err("VALIDATION_ERROR", "queryPattern must be a string when provided.")
    if queryId is not None and not isinstance(queryId, str):
        return _err("VALIDATION_ERROR", "queryId must be a string when provided.")

    if operation == "explain":
        if not isinstance(query, str) or not query.strip():
            return _err("VALIDATION_ERROR", "query is required for explain operation.")
    if operation == "get_slow_queries":
        if limit is not None and limit <= 0:
            return _err("VALIDATION_ERROR", "limit must be a positive number.")
        if minDuration is not None and minDuration < 0:
            return _err("VALIDATION_ERROR", "minDuration must be >= 0 when provided.")
    if operation == "get_stats":
        if minCalls is not None and minCalls < 0:
            return _err("VALIDATION_ERROR", "minCalls must be >= 0 when provided.")

    # resolve connection (ambient)
    conns = _load("pg_connections.json")
    def _redact_dsn(dsn: str) -> str:
        dsn = dsn.strip()
        dsn = re.sub(r"(?i)\bpassword\s*=\s*('[^']*'|\"[^\"]*\"|\S+)", "password=REDACTED", dsn)
        dsn = re.sub(r"(?i)(postgres(?:ql)?://[^:/?#\s]+):([^@/?#\s]+)@", r"\1:REDACTED@", dsn)
        return dsn

    connection_id = None
    if connectionString is not None and connectionString.strip():
        red = _redact_dsn(connectionString)
        existing = next((c for c in conns if c.get("connection_string_redacted") == red and c.get("status") != "deleted"), None)
        if existing:
            connection_id = existing.get("id")
            if existing.get("status") != "active":
                return _err("INVALID_TRANSITION", "Connection profile is not active.", connection_id=connection_id, status=existing.get("status"))
        else:
            # create new
            new_id = "pgc_" + hashlib.sha256((red + "|" + now).encode("utf-8")).hexdigest()[:24]
            row = {
                "id": new_id,
                "display_name": None,
                "connection_string_redacted": red,
                "connection_string_secret_ref": None,
                "host": None,
                "port": None,
                "database_name": None,
                "username": None,
                "ssl_mode": None,
                "status": "active",
                "last_tested_at": None,
                "last_error": None,
                "created_at": now,
                "updated_at": now,
            }
            conns.append(row)
            _save("pg_connections.json", conns)
            connection_id = new_id
    else:
        active = [c for c in conns if c.get("status") == "active"]
        if not active:
            return _err("UNAUTHORIZED", "No active connection profile available for this request.")
        connection_id = active[0].get("id")

    ops = _load("pg_operations.json")
    op_results = _load("pg_operation_results.json")

    op_id = "pgo_" + hashlib.sha256((operation + "|" + str(time.time()) + "|" + now).encode("utf-8")).hexdigest()[:24]
    params = {
        "operation": operation,
        "connectionString": None if connectionString is None else _redact_dsn(connectionString),
        "query": query,
        "analyze": analyze,
        "buffers": buffers,
        "verbose": verbose,
        "costs": costs,
        "format": format,
        "limit": limit,
        "minDuration": minDuration,
        "orderBy": orderBy,
        "includeNormalized": includeNormalized,
        "minCalls": minCalls,
        "queryPattern": queryPattern,
        "queryId": queryId,
    }

    op_row = {
        "id": op_id,
        "tool_name": "pg_manage_query",
        "connection_id": connection_id,
        "source_connection_id": None,
        "target_connection_id": None,
        "operation_group": "query",
        "requested_operation": operation,
        "params": params,
        "params_hash": hashlib.sha256(json.dumps(params, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest(),
        "status": "running",
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("pg_operations.json", ops)

    warnings = []

    def _finish(status, error_code=None, error_message=None):
        finished = datetime.datetime.utcnow().replace(microsecond=0)
        finished_s = finished.isoformat() + "Z"
        dur = int((time.time() - t0) * 1000)
        ops2 = _load("pg_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                allowed = {"queued":["running","cancelled"],"running":["succeeded","failed","cancelled"],"succeeded":[],"failed":[],"cancelled":[]}
                cur = r.get("status")
                if status not in allowed.get(cur, []):
                    return _err("INVALID_TRANSITION", "Illegal operation status transition.", from_status=cur, to_status=status)
                r["status"] = status
                r["finished_at"] = finished_s
                r["duration_ms"] = max(0, dur)
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["updated_at"] = finished_s
                break
        _save("pg_operations.json", ops2)
        return None

    # For "stats" persistence, we derive from prior pg_execute_query + pg_manage_query(explain) operations
    all_ops = _load("pg_operations.json")

    result_row = None
    if operation == "explain":
        # record explain output in operation_results with format match
        content_format = format
        content_json = None
        content_text = None
        # synthetic explain plan representation
        plan = {
            "Plan": {
                "Node Type": "Seq Scan",
                "Relation Name": "unknown",
                "Alias": "unknown",
                "Startup Cost": 0.0,
                "Total Cost": 0.0,
                "Plan Rows": 0,
                "Plan Width": 0,
            },
            "Settings": {
                "analyze": analyze,
                "buffers": buffers,
                "verbose": verbose,
                "costs": costs,
            },
            "Query": query,
        }
        if content_format == "json":
            content_json = plan
        else:
            # minimal text-ish
            content_text = f"EXPLAIN ({'ANALYZE' if analyze else 'ESTIMATE'}, FORMAT {content_format.upper()})\n{query}\n"
        result_row = {
            "id": "pgr_" + hashlib.sha256((op_id + "|explain_plan").encode("utf-8")).hexdigest()[:24],
            "operation_id": op_id,
            "result_type": "explain_plan",
            "content_format": content_format,
            "content_json": content_json,
            "content_text": content_text,
            "external_blob_ref": None,
            "rows_returned": None,
            "rows_affected": None,
            "warnings": warnings,
            "created_at": now,
            "updated_at": now,
        }
    elif operation in ("get_slow_queries","get_stats"):
        # compute stats from past operations for this connection_id that have query param
        def _extract_query(op):
            p = op.get("params") or {}
            q = p.get("query")
            if isinstance(q, str) and q.strip():
                return q.strip()
            return None
        # naive normalization: collapse whitespace
        def _norm(q):
            return re.sub(r"\s+", " ", q).strip().lower()

        # build per-normalized query counters
        agg = {}
        for o in all_ops:
            if o.get("connection_id") != connection_id:
                continue
            if o.get("tool_name") not in ("pg_execute_query","pg_manage_query","pg_execute_sql"):
                continue
            q = _extract_query(o)
            if not q:
                continue
            nq = _norm(q)
            h = hashlib.sha256(nq.encode("utf-8")).hexdigest()[:16]
            st = o.get("status")
            if st not in ("succeeded","failed"):
                continue
            dur = o.get("duration_ms")
            if not isinstance(dur, int):
                continue
            a = agg.setdefault(h, {"query_id": h, "normalized_query": nq, "sample_query": q, "calls": 0, "total_time_ms": 0, "mean_time_ms": 0.0, "failures": 0})
            a["calls"] += 1
            a["total_time_ms"] += dur
            if st == "failed":
                a["failures"] += 1

        rows = []
        for a in agg.values():
            if a["calls"] > 0:
                a["mean_time_ms"] = a["total_time_ms"] / float(a["calls"])
            # fake cache hit ratio using failures and calls
            a["cache_hit_ratio"] = max(0.0, min(1.0, 1.0 - (a["failures"] / float(max(1, a["calls"])))))
            if minCalls is not None and a["calls"] < minCalls and operation == "get_stats":
                continue
            if minDuration is not None and a["mean_time_ms"] < minDuration and operation == "get_slow_queries":
                continue
            if queryPattern is not None and queryPattern.lower() not in a["normalized_query"]:
                continue
            if not includeNormalized:
                a = dict(a)
                a.pop("normalized_query", None)
            rows.append(a)

        key_map = {
            "mean_time": "mean_time_ms",
            "total_time": "total_time_ms",
            "calls": "calls",
            "cache_hit_ratio": "cache_hit_ratio",
        }
        sk = key_map.get(orderBy, "mean_time_ms")
        rows.sort(key=lambda r: (r.get(sk) is None, r.get(sk)), reverse=True)

        # enforce limit safety and validation for get_slow_queries limit (positive already checked)
        hard_cap = 100
        effective_limit = int(limit) if limit is not None else 10
        if effective_limit > hard_cap:
            effective_limit = hard_cap
            warnings.append({"code": "LIMIT_CLAMPED", "message": f"limit clamped to server safety cap {hard_cap}."})
        out = rows[:effective_limit]

        result_row = {
            "id": "pgr_" + hashlib.sha256((op_id + "|stats_report").encode("utf-8")).hexdigest()[:24],
            "operation_id": op_id,
            "result_type": "stats_report",
            "content_format": "json",
            "content_json": {"operation": operation, "rows": out, "orderBy": orderBy, "limit": effective_limit},
            "content_text": None,
            "external_blob_ref": None,
            "rows_returned": len(out),
            "rows_affected": None,
            "warnings": warnings,
            "created_at": now,
            "updated_at": now,
        }
    elif operation == "reset_stats":
        # no external store; interpret as successful reset and report what would be reset
        scope = "all" if not queryId else "one"
        result_row = {
            "id": "pgr_" + hashlib.sha256((op_id + "|execution_summary").encode("utf-8")).hexdigest()[:24],
            "operation_id": op_id,
            "result_type": "execution_summary",
            "content_format": "json",
            "content_json": {"reset": scope, "queryId": queryId},
            "content_text": None,
            "external_blob_ref": None,
            "rows_returned": None,
            "rows_affected": None,
            "warnings": warnings,
            "created_at": now,
            "updated_at": now,
        }

    # persist result (unique per operation/result_type)
    if result_row is None:
        _finish("failed", "NO_RESULT", "No result generated.")
        return _err("CONFLICT", "Internal error: no result generated.", operation_id=op_id)

    existing = any(r.get("operation_id") == op_id and r.get("result_type") == result_row.get("result_type") for r in op_results)
    if existing:
        _finish("failed", "RESULT_CONFLICT", "Duplicate result for operation.")
        return _err("CONFLICT", "Duplicate result for operation.", operation_id=op_id)

    op_results.append(result_row)
    _save("pg_operation_results.json", op_results)

    fin_err = _finish("succeeded")
    if fin_err:
        return fin_err

    return {
        "operation": next((r for r in _load("pg_operations.json") if r.get("id") == op_id), op_row),
        "result": result_row
    }

def pg_execute_mutation(operation, table, connectionString=None, data=None, where=None, conflictColumns=None, returning=None, schema=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # validate
    if not isinstance(operation, str) or operation not in {"insert","update","delete","upsert"}:
        return _err("VALIDATION_ERROR", "operation must be one of insert/update/delete/upsert.", allowed=["insert","update","delete","upsert"])
    if not isinstance(table, str) or not table.strip():
        return _err("VALIDATION_ERROR", "table is required and must be a non-empty string.")
    if schema is None:
        schema = "public"
    if not isinstance(schema, str) or not schema.strip():
        return _err("VALIDATION_ERROR", "schema must be a non-empty string.")
    if connectionString is not None and not isinstance(connectionString, str):
        return _err("VALIDATION_ERROR", "connectionString must be a string when provided.")
    if where is not None and not isinstance(where, str):
        return _err("VALIDATION_ERROR", "where must be a string when provided.")
    if returning is not None and not isinstance(returning, str):
        return _err("VALIDATION_ERROR", "returning must be a string when provided.")
    if conflictColumns is not None:
        if not isinstance(conflictColumns, list) or any((not isinstance(c, str) or not c.strip()) for c in conflictColumns):
            return _err("VALIDATION_ERROR", "conflictColumns must be an array of non-empty strings when provided.")

    needs_data = operation in {"insert","update","upsert"}
    if needs_data:
        if data is None or not isinstance(data, dict):
            return _err("VALIDATION_ERROR", "data is required for insert/update/upsert and must be an object.")
    if operation in {"update","delete"}:
        if where is None or not isinstance(where, str) or not where.strip():
            return _err("VALIDATION_ERROR", "where is required for update/delete and must be a non-empty string.")
