        "status": "running",
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("pg_operations.json", ops)

    def _finish(status, error_code=None, error_message=None):
