        finished_s = finished.isoformat() + "Z"
        dur = int((time.time() - t0) * 1000)
        ops2 = _load("pg_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                allowed = {"queued":["running","cancelled"],"running":["succeeded","failed","cancelled"],"succeeded":[],"failed":[],"cancelled":[]}
                cur = r.get("status")
                if status not in allowed.get(cur, []):
                    return _err("INVALID_TRANSITION", "Illegal operation status transition.", from_status=cur, to_status=status)
                r["status"] = status
                r["finished_at"] = finished_s
                r["duration_ms"] = max(0, dur)
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["updated_at"] = finished_s
                break
        _save("pg_operations.json", ops2)
        return None

    # simulate row effects (no real table data). Must not succeed without effect.
    rows_affected = 0
    returning_rows = None

    if operation == "insert":
        rows_affected = 1
        if returning:
            returning_rows = [data]
    elif operation == "upsert":
        # upsert affects at least 1
        rows_affected = 1
        if returning:
            returning_rows = [data]
    elif operation == "update":
        # heuristic: update affects 1 unless where looks impossible
        if "1=0" in where.replace(" ", ""):
            rows_affected = 0
        else:
            rows_affected = 1
        if rows_affected == 0:
            _finish("failed", "NO_ROWS", "No rows matched update predicate.")
            return _err("NOT_FOUND", "No rows matched update predicate.", operation_id=op_id)
        if returning:
            returning_rows = [data]
    elif operation == "delete":
        if "1=0" in where.replace(" ", ""):
            rows_affected = 0
        else:
            rows_affected = 1
        if rows_affected == 0:
            _finish("failed", "NO_ROWS", "No rows matched delete predicate.")
            return _err("NOT_FOUND", "No rows matched delete predicate.", operation_id=op_id)
        if returning:
            returning_rows = []  # unknown rows; return empty set

    # mark related metadata cache entries stale for this connection/table
    obj_identities = [f"{schema}.{table}"]
    for e in cache:
        if e.get("connection_id") != connection_id:
            continue
        if e.get("object_identity") in obj_identities and e.get("status") == "current":
            # transition current -> stale
            e["status"] = "stale"
            e["updated_at"] = now
    _save("pg_object_metadata_cache.json", cache)

    # record execution_summary result indicating what changed (business rule)
    res = {
        "id": "pgr_" + hashlib.sha256((op_id + "|execution_summary").encode("utf-8")).hexdigest()[:24],
        "operation_id": op_id,
        "result_type": "execution_summary",
        "content_format": "json",
        "content_json": {
            "mutation": {
                "operation": operation,
                "schema": schema,
                "table": table,
                "where": where,
                "conflictColumns": conflictColumns,
                "returning": returning,
            },
            "rows_affected": rows_affected,
            "returning_rows": returning_rows,
        },
        "content_text": None,
        "external_blob_ref": None,
        "rows_returned": (len(returning_rows) if isinstance(returning_rows, list) else None),
        "rows_affected": rows_affected,
        "warnings": [],
        "created_at": now,
        "updated_at": now,
    }

    if any(r.get("operation_id") == op_id and r.get("result_type") == "execution_summary" for r in op_results):
        _finish("failed", "RESULT_CONFLICT", "Duplicate result for operation.")
        return _err("CONFLICT", "Duplicate result for operation.", operation_id=op_id)

    op_results.append(res)
    _save("pg_operation_results.json", op_results)

    fin_err = _finish("succeeded")
    if fin_err:
        return fin_err

    return {
        "operation": next((r for r in _load("pg_operations.json") if r.get("id") == op_id), op_row),
        "result": res
    }

def pg_manage_comments(operation, connectionString=None, objectType=None, objectName=None, schema=None, columnName=None, comment=None, includeSystemObjects=None, filterObjectType=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    op_id = None
    used_conn_id = None

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _resolve_or_create_conn(conn_str):
        nonlocal used_conn_id
        if conn_str is None:
            conns = _load("pg_connections.json")
            for c in conns:
                if c.get("status") == "active":
                    used_conn_id = c.get("id")
                    return c, conns
            return None, conns

        if not isinstance(conn_str, str) or not conn_str.strip():
            return _err("VALIDATION_ERROR", "connectionString must be a non-empty string when provided"), None

        import re
        s = conn_str.strip()
        redacted = re.sub(r"(?i)\bpassword\s*=\s*[^ \t\r\n;]+", "password=***", s)
        redacted = re.sub(r"(?i)(postgres(?:ql)?://[^:/@\s]+:)[^@/\s]+@", r"\1***@", redacted)

        conns = _load("pg_connections.json")
        for c in conns:
            if c.get("connection_string_redacted") == redacted and c.get("status") != "deleted":
                if c.get("status") != "active":
                    return _err("UNAUTHORIZED", "Connection is not active"), None
                used_conn_id = c.get("id")
                return c, conns

        now = _now()
        newc = {
            "id": _new_id("pgconn"),
            "display_name": None,
            "connection_string_redacted": redacted,
            "connection_string_secret_ref": None,
            "host": None,
            "port": None,
            "database_name": None,
            "username": None,
            "ssl_mode": None,
            "status": "active",
            "last_tested_at": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now,
        }
        conns.append(newc)
        _save("pg_connections.json", conns)
        used_conn_id = newc["id"]
        return newc, conns

    def _create_operation(params_store, requested_operation):
        nonlocal op_id
        ops = _load("pg_operations.json")
        now = _now()
        op_id = _new_id("pgop")
        op = {
            "id": op_id,
            "tool_name": "pg_manage_comments",
            "connection_id": used_conn_id,
            "source_connection_id": None,
            "target_connection_id": None,
            "operation_group": "comments",
            "requested_operation": requested_operation,
            "params": params_store,
            "params_hash": None,
            "status": "running",
            "started_at": now,
            "finished_at": None,
            "duration_ms": None,
            "error_code": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("pg_operations.json", ops)

    def _finish_operation(success, error_code=None, error_message=None):
        ops = _load("pg_operations.json")
        now = _now()
        for o in ops:
            if o.get("id") == op_id:
                o["status"] = "succeeded" if success else "failed"
                o["finished_at"] = now
                o["updated_at"] = now
                o["duration_ms"] = max(0, int((time.time() - t0) * 1000))
                o["error_code"] = error_code
                o["error_message"] = error_message
                break
        _save("pg_operations.json", ops)

    def _upsert_result(result_type, payload, warnings=None):
        results = _load("pg_operation_results.json")
        now = _now()
        if warnings is None:
            warnings = []
        existing = None
        for r in results:
            if r.get("operation_id") == op_id and r.get("result_type") == result_type:
                existing = r
                break
        if existing is None:
            results.append({
                "id": _new_id("pgres"),
                "operation_id": op_id,
                "result_type": result_type,
                "content_format": "json",
                "content_json": payload,
                "content_text": None,
                "external_blob_ref": None,
                "rows_returned": None,
                "rows_affected": None,
                "warnings": warnings,
                "created_at": now,
                "updated_at": now,
            })
        else:
            existing["content_format"] = "json"
            existing["content_json"] = payload
            existing["content_text"] = None
            existing["external_blob_ref"] = None
            existing["warnings"] = warnings
            existing["updated_at"] = now
        _save("pg_operation_results.json", results)

    def _canonical_schema(s):
        return "public" if s is None or s == "" else s

    # ---- Validate ----
    if not isinstance(operation, str):
        return _err("VALIDATION_ERROR", "operation is required and must be a string")
    if operation not in ("get", "set", "remove", "bulk_get"):
        return _err("VALIDATION_ERROR", "operation must be one of: get, set, remove, bulk_get")

    if includeSystemObjects is None:
        includeSystemObjects = False
    if includeSystemObjects is not None and not isinstance(includeSystemObjects, bool):
        return _err("VALIDATION_ERROR", "includeSystemObjects must be a boolean when provided")

    allowed_types = ("table", "column", "index", "constraint", "function", "trigger", "view", "sequence", "schema", "database")
    if filterObjectType is not None:
        if not isinstance(filterObjectType, str) or filterObjectType not in allowed_types:
            return _err("VALIDATION_ERROR", "filterObjectType must be a valid object type when provided")

    if operation in ("get", "set", "remove"):
        if not isinstance(objectType, str) or objectType not in allowed_types:
            return _err("VALIDATION_ERROR", "objectType is required and must be a valid object type for this operation")
        if not isinstance(objectName, str) or not objectName.strip():
            return _err("VALIDATION_ERROR", "objectName is required and must be a non-empty string for this operation")
        if objectType == "column":
            if not isinstance(columnName, str) or not columnName.strip():
                return _err("VALIDATION_ERROR", "columnName is required and must be a non-empty string when objectType is 'column'")
        if operation == "set":
            if not isinstance(comment, str):
                return _err("VALIDATION_ERROR", "comment is required and must be a string for set operation")

    # Resolve connection (ambient or provided)
    conn_res = _resolve_or_create_conn(connectionString)
    if isinstance(conn_res, dict) and conn_res.get("error"):
        return conn_res
    conn, _conns = conn_res
    if conn is None:
        return _err("UNAUTHORIZED", "No active connection available")

    effective_schema = _canonical_schema(schema)

    # Store all validated params (defaults applied)
    params_store = {
        "connectionString": connectionString,
        "operation": operation,
        "objectType": objectType,
        "objectName": objectName,
        "schema": effective_schema if operation != "bulk_get" else schema,  # bulk_get doesn't require schema
        "columnName": columnName,
        "comment": comment,
        "includeSystemObjects": includeSystemObjects,
        "filterObjectType": filterObjectType,
    }

    _create_operation(params_store, requested_operation=operation)

    cache = _load("pg_object_metadata_cache.json")
    warnings = []

    def _identity_for(obj_type, sch, obj_name, col_name):
        if obj_type == "database":
            return obj_name
        if obj_type == "schema":
            return obj_name
        if obj_type == "column":
            return f"{sch}.{obj_name}.{col_name}"
        return f"{sch}.{obj_name}"

    def _find_cache_entry(conn_id, identity):
        for e in cache:
            if e.get("connection_id") == conn_id and e.get("object_identity") == identity:
                return e
        return None

    def _upsert_cache(obj_type, sch, obj_name, identity, comment_text):
        now = _now()
        e = _find_cache_entry(used_conn_id, identity)
        if e is None:
            cache.append({
                "id": _new_id("pgmeta"),
                "connection_id": used_conn_id,
                "schema": sch,
                "object_type": obj_type,
                "object_name": obj_name,
                "object_identity": identity,
                "definition": None,
                "comment": comment_text,
                "attributes": {},
                "observed_at": now,
                "status": "current",
                "created_at": now,
                "updated_at": now,
            })
        else:
            e["comment"] = comment_text
            e["observed_at"] = now
            e["status"] = "current" if e.get("status") != "deleted" else e.get("status")
            e["updated_at"] = now

    def _mark_deleted(identity):
        now = _now()
        e = _find_cache_entry(used_conn_id, identity)
        if e is None:
            return False
        if e.get("status") == "deleted":
            return True  # idempotent remove
        # lifecycle transition current/stale -> deleted allowed
        if e.get("status") not in ("current", "stale"):
            return False
        e["status"] = "deleted"
        e["comment"] = None
        e["observed_at"] = now
        e["updated_at"] = now
        return True

    try:
        if operation == "bulk_get":
            # Discovery: return matching current/stale entries, optionally include system objects.
            # "System objects" heuristic: schemas starting with pg_ or information_schema, or object_name starting with pg_.
            out = []
            for e in cache:
                if e.get("connection_id") != used_conn_id:
                    continue
                if e.get("object_type") not in allowed_types:
                    continue
                if filterObjectType is not None and e.get("object_type") != filterObjectType:
                    continue
                if not includeSystemObjects:
                    sch = e.get("schema") or ""
                    on = e.get("object_name") or ""
                    if sch.startswith("pg_") or sch == "information_schema" or on.startswith("pg_"):
                        continue
                if e.get("comment") is None:
                    continue
                out.append({
                    "objectType": e.get("object_type"),
                    "schema": e.get("schema"),
                    "objectName": e.get("object_name"),
                    "objectIdentity": e.get("object_identity"),
                    "comment": e.get("comment"),
                    "status": e.get("status"),
                    "observedAt": e.get("observed_at"),
                })
            _save("pg_object_metadata_cache.json", cache)
            _upsert_result("comments_dump", {"operation": "bulk_get", "count": len(out), "comments": out}, warnings=warnings)
            _finish_operation(True)
            return {"operation": {"id": op_id, "status": "succeeded"}, "comments": out}

        # get/set/remove
        if objectType in ("database", "schema"):
            effective_schema_for_identity = None
        else:
            effective_schema_for_identity = effective_schema

        identity = _identity_for(objectType, effective_schema_for_identity, objectName.strip(), columnName.strip() if isinstance(columnName, str) else None)

        if operation == "get":
            e = _find_cache_entry(used_conn_id, identity)
            resolved = None
            if e and e.get("status") != "deleted":
                resolved = e.get("comment")
            _upsert_result("comments_dump", {"operation": "get", "objectIdentity": identity, "comment": resolved}, warnings=warnings)
            _finish_operation(True)
            return {"operation": {"id": op_id, "status": "succeeded"}, "objectIdentity": identity, "comment": resolved}

        if operation == "set":
            if not objectName.strip():
                _finish_operation(False, "VALIDATION_ERROR", "objectName empty")
                return _err("VALIDATION_ERROR", "objectName must be non-empty")
            _upsert_cache(objectType, effective_schema_for_identity, objectName.strip(), identity, comment)
            _save("pg_object_metadata_cache.json", cache)
            _upsert_result("comments_dump", {"operation": "set", "objectIdentity": identity, "comment": comment}, warnings=warnings)
            _finish_operation(True)
            return {"operation": {"id": op_id, "status": "succeeded"}, "objectIdentity": identity, "comment": comment}

        if operation == "remove":
            ok = _mark_deleted(identity)
            if not ok:
                # No success without effect: if entry doesn't exist, treat as NOT_FOUND.
                _finish_operation(False, "NOT_FOUND", "Comment not found")
                return _err("NOT_FOUND", "Comment not found", object_identity=identity)
            _save("pg_object_metadata_cache.json", cache)
            _upsert_result("comments_dump", {"operation": "remove", "objectIdentity": identity, "comment": None}, warnings=warnings)
            _finish_operation(True)
            return {"operation": {"id": op_id, "status": "succeeded"}, "objectIdentity": identity, "comment": None}

        _finish_operation(False, "VALIDATION_ERROR", "Invalid operation")
        return _err("VALIDATION_ERROR", "Invalid operation")
    except Exception as e:
        try:
            _finish_operation(False, "INTERNAL_ERROR", str(e))
        except Exception:
            pass
        return _err("CONFLICT", "Internal error", detail=str(e))

def pg_list_connections(authToken, status=None, host=None, databaseName=None, username=None, search=None, pageSize=None, pageToken=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _normalize_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str):
            return None
        t = tok.strip()
        if not t:
            return None
        if t.lower().startswith("bearer "):
            t = t[7:].strip()
        return t or None

    def _load_rows(name):
        d = _load(name)
        if isinstance(d, dict) and "rows" in d and isinstance(d.get("rows"), list):
            return d["rows"]
        if isinstance(d, list):
            return d
        return []

    def _save_rows(name, rows):
        _save(name, rows)

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{hashlib.sha1(os.urandom(16)).hexdigest()[:10]}"

    def _log(status_code, credential_used, meta=None):
        logs = _load_rows("pg_request_logs.json")
        logs.append({
            "id": _gen_id("pgrl"),
            "endpoint": "pg_list_connections",
            "credential": credential_used,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {}
        })
        _save_rows("pg_request_logs.json", logs)

    def _resolve_principal(tok):
        # Vendor auth tokens may be stored in various files; accept by id or client-visible value.
        t = _normalize_token(tok)
        if t is None:
            return None
        candidates = []
        for fname in ("auth_tokens.json", "api_keys.json", "credentials.json", "pg_credentials.json", "pg_api_keys.json", "tokens.json"):
            for row in _load_rows(fname):
                if not isinstance(row, dict):
                    continue
                candidates.append(row)
        # Also accept connection ids as bearer in this dataset (audit examples pass pgconn_... as authToken).
        if t.startswith("pgconn_"):
            # If any active connection exists with this id, consider the caller authenticated for listing.
            conns = _load_rows("pg_connections.json")
            for c in conns:
                if isinstance(c, dict) and c.get("id") == t and c.get("status") != "deleted":
                    return {"id": t, "token": t, "scopes": ["connections:read", "operations:read", "connections:write", "operations:write"], "status": "active"}
        for row in candidates:
            if not isinstance(row, dict):
                continue
            if row.get("id") == t or row.get("token") == t or row.get("key") == t or row.get("value") == t:
                st = row.get("status")
                if st in (None, "active", "enabled", "valid"):
                    return row
        return None

    def _parse_cursor(tok):
        if tok is None:
            return 0
        if not isinstance(tok, str) or not tok:
            return 0
        # Accept opaque base64 cursor; also tolerate arbitrary strings by treating as 0.
        try:
            raw = base64.urlsafe_b64decode(tok.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("offset:"):
                return max(0, int(s.split(":", 1)[1]))
        except Exception:
            return 0
        return 0

    def _make_cursor(offset):
        raw = f"offset:{int(offset)}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs first
    principal = _resolve_principal(authToken)
    cred_used = _normalize_token(authToken) or authToken
    if principal is None:
        _log("UNAUTHORIZED", cred_used)
        return _err("UNAUTHORIZED", "Missing or invalid authToken.")

    if status is not None and status not in ("active", "disabled", "deleted"):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=["active", "disabled", "deleted"])
    if host is not None and not isinstance(host, str):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "host must be a string.")
    if databaseName is not None and not isinstance(databaseName, str):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "databaseName must be a string.")
    if username is not None and not isinstance(username, str):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "username must be a string.")
    if search is not None and not isinstance(search, str):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "search must be a string.")

    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200.")
    if sortBy is None:
        sortBy = "updated_at"
    if sortBy not in ("created_at", "updated_at", "display_name", "last_tested_at"):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "Invalid sortBy.", allowed=["created_at", "updated_at", "display_name", "last_tested_at"])
    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "Invalid sortOrder.", allowed=["asc", "desc"])

    offset = _parse_cursor(pageToken)

    # Filter/search/sort/paginate
    rows = _load_rows("pg_connections.json")
    out = []
    q = (search or "").strip().lower()
    for r in rows:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if host is not None and r.get("host") != host:
            continue
        if databaseName is not None and r.get("database_name") != databaseName:
            continue
        if username is not None and r.get("username") != username:
            continue
        if q:
            dn = (r.get("display_name") or "").lower()
            h = (r.get("host") or "").lower()
            if q not in dn and q not in h:
                continue
        out.append(r)

    def _sort_key(r):
        v = r.get(sortBy)
        # Keep stable; None sorts last in asc, first in desc by using tuple.
        return (v is None, v)

    out.sort(key=_sort_key, reverse=(sortOrder == "desc"))

    total = len(out)
    page = out[offset: offset + pageSize]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _make_cursor(next_offset) if has_more else None

    _log("OK", cred_used, meta={"returned": len(page), "total": total, "offset": offset})

    return {
        "connections": page,
        "page": {
            "page_size": pageSize,
            "total": total,
            "has_more": has_more,
            "next_page_token": next_cursor
        }
    }

def pg_get_connection(authToken, id, **_extra):
    import json, os, datetime, time, hashlib

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")

