        if not isinstance(dsn, str) or not dsn.strip():
            return False, None, None
        dsn = dsn.strip()

        # If caller passed a connection id as "connectionString" (seen in audit args), treat as reference
        if dsn.startswith("pgconn_"):
            return True, {"ref_connection_id": dsn}, f"ref:{dsn}"

        # URL form
        if dsn.lower().startswith("postgres://") or dsn.lower().startswith("postgresql://"):
            u = urllib.parse.urlparse(dsn)
            if not u.hostname:
                return False, None, None
            dbname = (u.path or "").lstrip("/") or None
            user = urllib.parse.unquote(u.username) if u.username else None
            pwd = urllib.parse.unquote(u.password) if u.password else None
            port = u.port
            qs = urllib.parse.parse_qs(u.query or "")
            sslm = (qs.get("sslmode", [None])[0] if isinstance(qs, dict) else None)
