            if dbname:
                red += f"/{dbname}"
            if sslm:
                red += f"?sslmode={sslm}"
            return True, {"host": u.hostname, "port": port, "database_name": dbname, "username": user, "ssl_mode": sslm, "has_password": pwd is not None}, red

        # key=value DSN
        parts = re.findall(r"""(\w+)\s*=\s*('[^']*'|"[^"]*"|[^\s]+)""", dsn)
        if parts:
            kv = {}
            for k, v in parts:
                if (v.startswith("'") and v.endswith("'")) or (v.startswith('"') and v.endswith('"')):
                    v = v[1:-1]
                kv[k.lower()] = v
            host = kv.get("host") or kv.get("hostname")
            port = kv.get("port")
            dbname = kv.get("dbname") or kv.get("database")
            user = kv.get("user") or kv.get("username")
            pwd = kv.get("password")
            sslm = kv.get("sslmode")
            if host is None:
                return False, None, None
            port_i = None
            if port is not None:
                try:
                    port_i = int(port)
                except Exception:
                    return False, None, None
            # Redacted DSN (do not include password)
            red_parts = []
            for k in ("host", "port", "dbname", "user", "sslmode"):
                if k in kv and kv.get(k) not in (None, ""):
                    val = kv.get(k)
                    if " " in str(val):
                        val = "'" + str(val).replace("'", "\\'") + "'"
                    red_parts.append(f"{k}={val}")
            red = " ".join(red_parts) if red_parts else f"host={host}"
            return True, {"host": host, "port": port_i, "database_name": dbname, "username": user, "ssl_mode": sslm, "has_password": pwd is not None}, red

