        return _err("VALIDATION_ERROR", "id must be a non-empty string when provided.")
    if displayName is not None and not isinstance(displayName, str):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "displayName must be a string.")
    if sslMode is not None and sslMode not in ("disable", "allow", "prefer", "require", "verify-ca", "verify-full"):
