    if status is not None and status not in ("active", "disabled"):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "Invalid status for upsert (must be 'active' or 'disabled').")
    if testConnection is None:
        testConnection = False
    if not isinstance(testConnection, bool):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "testConnection must be a boolean.")

    conns = _load_rows("pg_connections.json")

    # Resolve target row
    target = None
    if id is not None:
        id = id.strip()
        for r in conns:
            if isinstance(r, dict) and r.get("id") == id:
                target = r
                break
        if target is None:
            _log("NOT_FOUND", cred_used, meta={"id": id})
            return _err("NOT_FOUND", "Connection not found for update.", id=id)

    parsed = None
    redacted = None
    if connectionString is not None:
        ok, parsed, redacted = _parse_pg_dsn(connectionString)
        if not ok:
            _log("VALIDATION_ERROR", cred_used)
            return _err("VALIDATION_ERROR", "Malformed connectionString.")
        # If connectionString references existing connection id, treat it as a lookup (idempotent pointer)
        if parsed and "ref_connection_id" in parsed:
            ref_id = parsed["ref_connection_id"]
            ref = None
            for r in conns:
                if isinstance(r, dict) and r.get("id") == ref_id:
                    ref = r
                    break
            if ref is None:
                _log("NOT_FOUND", cred_used, meta={"ref_connection_id": ref_id})
                return _err("NOT_FOUND", "Referenced connection id not found.", id=ref_id)
            # If caller also provided id and it differs, allow update of id record using ref's redacted key? Too ambiguous.
            # Treat as: operate on referenced connection as the resolved one unless id explicitly points elsewhere.
            if target is None:
                target = ref
                id = ref_id
        else:
            # Deduplicate by redacted string uniqueness
            existing = None
            for r in conns:
                if isinstance(r, dict) and r.get("connection_string_redacted") == redacted:
                    existing = r
                    break
            if target is None:
                target = existing
            else:
                # updating an existing row; ensure uniqueness if changing redacted string
                if existing is not None and existing.get("id") != target.get("id"):
                    _log("CONFLICT", cred_used, meta={"conflict_with": existing.get("id")})
                    return _err("CONFLICT", "connectionString conflicts with an existing connection_string_redacted.", conflict_with=existing.get("id"))

    # If still no target, create a new one requires connectionString to resolve key
    creating = False
    if target is None:
        if connectionString is None:
            _log("VALIDATION_ERROR", cred_used)
            return _err("VALIDATION_ERROR", "connectionString is required when creating a new connection (or provide id of an existing connection).")
        if parsed is None or "ref_connection_id" in (parsed or {}):
            _log("VALIDATION_ERROR", cred_used)
            return _err("VALIDATION_ERROR", "A concrete PostgreSQL connectionString is required to create a new connection.")
        creating = True
        new_id = _gen_id("pgconn")
        now = _now()
        target = {
            "id": new_id,
            "display_name": None,
            "connection_string_redacted": redacted,
            "connection_string_secret_ref": (f"secretref:{new_id}" if parsed.get("has_password") else None),
            "host": parsed.get("host"),
            "port": parsed.get("port"),
            "database_name": parsed.get("database_name"),
            "username": parsed.get("username"),
            "ssl_mode": sslMode if sslMode is not None else parsed.get("ssl_mode"),
            "status": status if status is not None else "active",
            "last_tested_at": None,
            "last_error": None,
            "created_at": now,
            "updated_at": now
        }
        if displayName is not None:
            target["display_name"] = displayName
        conns.append(target)
    else:
        # Update fields
        now = _now()
        if displayName is not None:
            target["display_name"] = displayName
        if connectionString is not None and parsed is not None and "ref_connection_id" not in parsed:
            target["connection_string_redacted"] = redacted
            target["host"] = parsed.get("host")
            target["port"] = parsed.get("port")
            target["database_name"] = parsed.get("database_name")
            target["username"] = parsed.get("username")
            # only overwrite ssl_mode from DSN if not explicitly set
            if sslMode is None:
                target["ssl_mode"] = parsed.get("ssl_mode")
            # update secret ref if password present; never store plaintext
            if parsed.get("has_password"):
                target["connection_string_secret_ref"] = target.get("connection_string_secret_ref") or f"secretref:{target.get('id')}"
        if sslMode is not None:
            target["ssl_mode"] = sslMode
        if status is not None:
            # upsert only allows active/disabled and must honor lifecycle (no deleted)
            if target.get("status") == "deleted":
                _log("INVALID_TRANSITION", cred_used)
                return _err("INVALID_TRANSITION", "Cannot update a deleted connection. Create a new one or restore is not supported.")
            if target.get("status") != status:
                # lifecycle: active<->disabled allowed
                if target.get("status") not in ("active", "disabled") or status not in ("active", "disabled"):
                    _log("INVALID_TRANSITION", cred_used)
                    return _err("INVALID_TRANSITION", "Invalid lifecycle transition for upsert.")
                target["status"] = status
        target["updated_at"] = now

    # Validate constraints: port range, unique(connection_string_redacted)
    port = target.get("port")
    if port is not None:
        if not isinstance(port, int) or port < 1 or port > 65535:
            _log("VALIDATION_ERROR", cred_used)
            return _err("VALIDATION_ERROR", "port must be between 1 and 65535 when present.")
    # uniqueness check across store
    red = target.get("connection_string_redacted")
    if not isinstance(red, str) or not red.strip():
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "connection_string_redacted could not be derived.")
    for r in conns:
        if r is target:
            continue
        if isinstance(r, dict) and r.get("connection_string_redacted") == red and r.get("id") != target.get("id"):
            _log("CONFLICT", cred_used, meta={"conflict_with": r.get("id")})
            return _err("CONFLICT", "connection_string_redacted must be unique.", conflict_with=r.get("id"))

    # Optional testConnection: offline simulation updates timestamps and clears/sets last_error deterministically
    if testConnection:
        target["last_tested_at"] = _now()
        # Mark as "ok" by clearing last_error; real system would actually attempt a connection.
        target["last_error"] = None
        target["updated_at"] = _now()

    _save_rows("pg_connections.json", conns)
    _log("OK", cred_used, meta={"id": target.get("id"), "created": creating})

    return {"connection": target}

