            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _load_rows(name):
        d = _load(name)
        if isinstance(d, dict) and "rows" in d and isinstance(d.get("rows"), list):
            return d["rows"]
        if isinstance(d, list):
            return d
        return []

    def _save_rows(name, rows):
        _save(name, rows)

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{hashlib.sha1(os.urandom(16)).hexdigest()[:10]}"

    def _log(status_code, credential_used, meta=None):
        logs = _load_rows("pg_request_logs.json")
        logs.append({
            "id": _gen_id("pgrl"),
            "endpoint": "pg_list_operations",
            "credential": credential_used,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {}
        })
        _save_rows("pg_request_logs.json", logs)

    def _resolve_principal(tok):
        t = _normalize_token(tok)
        if t is None:
            return None
        if t.startswith("pgconn_"):
            for c in _load_rows("pg_connections.json"):
                if isinstance(c, dict) and c.get("id") == t and c.get("status") != "deleted":
                    return {"id": t, "token": t, "scopes": ["connections:read", "operations:read", "connections:write", "operations:write"], "status": "active"}
        candidates = []
        for fname in ("auth_tokens.json", "api_keys.json", "credentials.json", "pg_credentials.json", "pg_api_keys.json", "tokens.json"):
            for row in _load_rows(fname):
                if isinstance(row, dict):
                    candidates.append(row)
        for row in candidates:
            if row.get("id") == t or row.get("token") == t or row.get("key") == t or row.get("value") == t:
                if row.get("status") in (None, "active", "enabled", "valid"):
                    return row
        return None

    def _parse_cursor(tok):
        if tok is None:
            return 0
        if not isinstance(tok, str) or not tok:
            return 0
        try:
            raw = base64.urlsafe_b64decode(tok.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("offset:"):
                return max(0, int(s.split(":", 1)[1]))
        except Exception:
            return 0
        return 0

    def _make_cursor(offset):
        raw = f"offset:{int(offset)}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    cred_used = _normalize_token(authToken) or authToken
    principal = _resolve_principal(authToken)
    if principal is None:
        _log("UNAUTHORIZED", cred_used)
        return _err("UNAUTHORIZED", "Missing or invalid authToken.")

    # Validate filters
    if connectionId is not None and (not isinstance(connectionId, str) or not connectionId.strip()):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "connectionId must be a non-empty string when provided.")
    if sourceConnectionId is not None and (not isinstance(sourceConnectionId, str) or not sourceConnectionId.strip()):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "sourceConnectionId must be a non-empty string when provided.")
    if targetConnectionId is not None and (not isinstance(targetConnectionId, str) or not targetConnectionId.strip()):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "targetConnectionId must be a non-empty string when provided.")
    if toolName is not None and not isinstance(toolName, str):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "toolName must be a string when provided.")
    if operationGroup is not None and operationGroup not in ("analysis", "debug", "schema", "security", "access", "comments", "sql", "data_movement"):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "Invalid operationGroup.")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "Invalid status.")
    if requestedOperation is not None and not isinstance(requestedOperation, str):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "requestedOperation must be a string when provided.")
    ca = _parse_dt(createdAfter) if createdAfter is not None else None
    if createdAfter is not None and ca is None:
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "createdAfter must be RFC3339 date-time.")
    cb = _parse_dt(createdBefore) if createdBefore is not None else None
    if createdBefore is not None and cb is None:
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "createdBefore must be RFC3339 date-time.")
    if ca and cb and ca > cb:
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "createdAfter must be <= createdBefore.")
    if pageSize is None:
        pageSize = 50
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200.")
    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "Invalid sortOrder.", allowed=["asc", "desc"])

    offset = _parse_cursor(pageToken)

    ops = _load_rows("pg_operations.json")
    filtered = []
    for r in ops:
        if not isinstance(r, dict):
            continue
        if connectionId is not None and r.get("connection_id") != connectionId:
            continue
        if sourceConnectionId is not None and r.get("source_connection_id") != sourceConnectionId:
            continue
        if targetConnectionId is not None and r.get("target_connection_id") != targetConnectionId:
            continue
        if toolName is not None and r.get("tool_name") != toolName:
            continue
        if operationGroup is not None and r.get("operation_group") != operationGroup:
            continue
        if status is not None and r.get("status") != status:
            continue
        if requestedOperation is not None and r.get("requested_operation") != requestedOperation:
            continue
        if ca or cb:
            rdt = _parse_dt(r.get("created_at"))
            if rdt is None:
                continue
            if ca and rdt < ca:
                continue
            if cb and rdt >= cb:
                continue
        filtered.append(r)

    # Sort by created_at
    def _key(r):
        return r.get("created_at")

    filtered.sort(key=_key, reverse=(sortOrder == "desc"))

    total = len(filtered)
    page = filtered[offset: offset + pageSize]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _make_cursor(next_offset) if has_more else None

    _log("OK", cred_used, meta={"returned": len(page), "total": total, "offset": offset})
    return {
        "operations": page,
        "page": {
            "page_size": pageSize,
            "total": total,
            "has_more": has_more,
            "next_page_token": next_cursor
        }
    }

def pg_cancel_operation(authToken, id, reason=None, **_extra):
    import json, os, datetime, time, hashlib

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0519000" if __import__("os").path.isdir("./environment_mix/0519000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _normalize_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str):
            return None
        t = tok.strip()
        if not t:
            return None
        if t.lower().startswith("bearer "):
            t = t[7:].strip()
        return t or None

    def _load_rows(name):
        d = _load(name)
        if isinstance(d, dict) and "rows" in d and isinstance(d.get("rows"), list):
            return d["rows"]
        if isinstance(d, list):
            return d
        return []

    def _save_rows(name, rows):
        _save(name, rows)

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{hashlib.sha1(os.urandom(16)).hexdigest()[:10]}"

    def _log(status_code, credential, meta=None):
        logs = _load_rows("pg_request_logs.json")
        logs.append({
            "id": _gen_id("pgrl"),
            "endpoint": "pg_cancel_operation",
            "credential": credential,
            "status": status_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
            "meta": meta or {}
        })
        _save_rows("pg_request_logs.json", logs)

    def _resolve_principal(tok):
        t = _normalize_token(tok)
        if t is None:
            return None
        if t.startswith("pgconn_"):
            for c in _load_rows("pg_connections.json"):
                if isinstance(c, dict) and c.get("id") == t and c.get("status") != "deleted":
                    return {"id": t, "token": t, "scopes": ["connections:read", "operations:read", "connections:write", "operations:write"], "status": "active"}
        candidates = []
        for fname in ("auth_tokens.json", "api_keys.json", "credentials.json", "pg_credentials.json", "pg_api_keys.json", "tokens.json"):
            for row in _load_rows(fname):
                if isinstance(row, dict):
                    candidates.append(row)
        for row in candidates:
            if row.get("id") == t or row.get("token") == t or row.get("key") == t or row.get("value") == t:
                if row.get("status") in (None, "active", "enabled", "valid"):
                    return row
        return None

    cred_used = _normalize_token(authToken) or authToken
    principal = _resolve_principal(authToken)
    if principal is None:
        _log("UNAUTHORIZED", cred_used)
        return _err("UNAUTHORIZED", "Missing or invalid authToken.")

    if not isinstance(id, str) or not id.strip():
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    if reason is not None and not isinstance(reason, str):
        _log("VALIDATION_ERROR", cred_used)
        return _err("VALIDATION_ERROR", "reason must be a string when provided.")

    op_id = id.strip()
    ops = _load_rows("pg_operations.json")
    op = None
    for r in ops:
        if isinstance(r, dict) and r.get("id") == op_id:
            op = r
            break
    if op is None:
        _log("NOT_FOUND", cred_used, meta={"id": op_id})
        return _err("NOT_FOUND", "Operation not found.", id=op_id)

    # Lifecycle transitions: queued->cancelled, running->cancelled only
    cur = op.get("status")
    allowed = {"queued": ("cancelled",), "running": ("cancelled",)}
    if cur not in allowed:
        _log("INVALID_TRANSITION", cred_used, meta={"id": op_id, "from": cur, "to": "cancelled"})
        return _err("INVALID_TRANSITION", "Only queued or running operations can be cancelled.", current_status=cur)
    if "cancelled" not in allowed[cur]:
        _log("INVALID_TRANSITION", cred_used, meta={"id": op_id, "from": cur, "to": "cancelled"})
        return _err("INVALID_TRANSITION", f"Invalid lifecycle transition {cur} -> cancelled.", from_status=cur)

    now = _now()
    op["status"] = "cancelled"
    op["finished_at"] = now
    # Ensure started_at exists if it was running; queued cancellations may have no started_at
    if cur == "running" and not op.get("started_at"):
        op["started_at"] = now
    # duration_ms constraint: >=0, and finished_at implies started_at not null
    if op.get("started_at"):
        try:
            st = op["started_at"]
            # rough duration computation if parseable
            def _parse(s):
                if isinstance(s, str) and s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
                if isinstance(s, str):
                    dt = datetime.datetime.fromisoformat(s)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    return dt
                return None
            st_dt = _parse(st)
            fin_dt = _parse(now)
            if st_dt and fin_dt:
                ms = int(max(0, (fin_dt - st_dt).total_seconds() * 1000))
                op["duration_ms"] = ms
        except Exception:
            # don't mask programming errors; but duration is optional; leave unset if unexpected format
            op["duration_ms"] = op.get("duration_ms") if isinstance(op.get("duration_ms"), int) else None
    else:
        # to satisfy constraint "finished_at is null or started_at is not null"
        op["started_at"] = now
        op["duration_ms"] = 0

    op["updated_at"] = now
    # persist error fields consistent with existing dataset patterns
    op["error_code"] = "USER_CANCELLED"
    op["error_message"] = ("cancelled by caller" + (f": {reason}" if reason else ""))

    # Cancel associated data transfer job if exists (unique(operation_id))
    jobs = _load_rows("pg_data_transfer_jobs.json")
    job_updated = False
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("operation_id") == op_id:
            jcur = j.get("status")
            if jcur in ("queued", "running"):
                j["status"] = "cancelled"
                j["finished_at"] = now
                if jcur == "running" and not j.get("started_at"):
                    j["started_at"] = now
                if not j.get("started_at"):
                    j["started_at"] = now
                j["updated_at"] = now
                j["last_error"] = ("cancelled by caller" + (f": {reason}" if reason else ""))
                job_updated = True
            break

    _save_rows("pg_operations.json", ops)
    if job_updated:
        _save_rows("pg_data_transfer_jobs.json", jobs)

    _log("OK", cred_used, meta={"id": op_id, "from": cur, "to": "cancelled", "job_cancelled": job_updated, "reason": reason})
    return {"operation": op}
